# =============================================================================
# RETRO LENS  -  one single, self-contained file
#   21 analog photo filters, one density slider, stacked layers, undo/redo,
#   shareable look links, saved looks, a split Download button (.png/.jpg/.webp)
#   and an optional REST API. Every picture, font and script is inside this file.
#
# HOW TO RUN
#   1. Save this as  app.R  in an empty folder, open it in RStudio, click "Run App".
#   2. Or, from the R Console (works from any folder):
#        shiny::runApp(source("C:/path/to/app.R")$value)
#
# PACKAGES (R >= 4.1)
#   Required:  install.packages(c("shiny", "magick", "base64enc", "cachem", "later", "jsonlite"))
#   Optional:  install.packages(c("future", "promises"))   # big Downloads render in the
#                                                          # background; other visitors
#                                                          # are not held up
#              install.packages("plumber")                 # the REST API (see below)
#              install.packages("renv")                    # pin exact package versions
#
# REST API (optional, run it in its own R session)
#   source("app.R"); retro_lens_api()                      # http://127.0.0.1:8000
#   curl -X POST --data-binary @photo.jpg "http://127.0.0.1:8000/filter?name=Noir&density=20" -o out.jpg
#
# PINNED PACKAGE VERSIONS (optional)
#   A lock file records the exact version of every package, so anyone can rebuild
#   the same environment. It has to be created on YOUR machine (it lists what you
#   have installed). Put app.R in its own folder, then run once:
#        source("app.R"); lock_dependencies()
#   That writes renv.lock. Anyone else then runs  renv::restore()  in that folder.
#
# Third-party parts embedded below
#   Inter and Playfair Display fonts  - SIL Open Font License 1.1 (fontsource builds)
#   Lenis smooth scrolling            - MIT License, Copyright (c) 2024 darkroom.engineering
# =============================================================================


# Loaded first (Shiny sources R/ alphabetically, before app.R).
# Needs R >= 4.1 (native pipe, \(x) lambdas).

# Clear message instead of a cryptic "there is no package called ..." later on.
.needed <- c("shiny", "magick", "base64enc", "cachem", "later", "jsonlite")
.missing <- .needed[!vapply(.needed, requireNamespace, logical(1), quietly = TRUE)]
if (length(.missing)) {
  stop("Please install the missing package(s) first:\n  install.packages(c(",
       paste0('"', .missing, '"', collapse = ", "), "))", call. = FALSE)
}
rm(.needed, .missing)

library(shiny)
library(magick)

# "Hosted" mode is for small shared servers (shinyapps.io gives a free app about 1 GB of
# memory in total). It is switched on automatically on shinyapps.io, or by putting
# options(retrolens.hosted = TRUE) at the very top of app.R, or by setting the
# environment variable RETROLENS_HOSTED=1. What changes: photos are limited to 3000 px
# on the long side, no extra background R processes are started, and the preview cache
# is smaller. On your own computer none of this applies.
if (identical(Sys.getenv("R_CONFIG_ACTIVE"), "shinyapps") || nzchar(Sys.getenv("RETROLENS_HOSTED"))) {
  options(retrolens.hosted = TRUE)
}
.hosted <- isTRUE(getOption("retrolens.hosted", FALSE))

# Phone photos are routinely 5-15 MB; Shiny's default limit is 5 MB.
options(shiny.maxRequestSize = 30 * 1024^2)

# Rendered previews are cached (as small JPEG strings), shared between sessions.
shinyOptions(cache = cachem::cache_mem(max_size = (if (.hosted) 64 else 128) * 1024^2))

# Optional: with `future` + `promises` installed, the big full-size Download
# renders in a background worker, so other visitors are not frozen meanwhile.
# Without them everything still works; Download just renders in the main process.
# (Skipped in hosted mode: every extra R process would eat into the small memory budget.)
if (!.hosted && requireNamespace("future", quietly = TRUE) && requireNamespace("promises", quietly = TRUE)) {
  local({
    cores <- tryCatch(parallelly::availableCores(), error = function(e) 2L)
    try(future::plan(future::multisession, workers = max(2L, min(4L, as.integer(cores) - 1L))),
        silent = TRUE)
  })
}


# ---- R/filters.R ----
# =========================================================
# FILTERS
#   Pure functions: magick image in, magick image out. No Shiny code here,
#   so they can be unit-tested (tests/testthat) and reused (plumber, scripts).
#
#   Density maths
#     slider  -100 .. 100  ->  t = density_to_t(slider)
#     t = 1   the filter's normal look      t = 0  the untouched photo
#     t > 1   "pushed further"              t < 0  the opposite effect
#   Every look "pushes further" and (where a sensible opposite exists) inverts
#   smoothly, because blend-type filters extrapolate between the photo and
#   the effect instead of clamping at 100%.
# =========================================================

library(magick)

`%||%` <- function(a, b) if (is.null(a)) b else a

# ---- Density scale --------------------------------------------------------
#   slider -100 -> t = -1   (opposite effect)
#   slider  -50 -> t =  0   (original photo)
#   slider    0 -> t =  1   (filter's normal look)
#   slider  100 -> t =  2   (pushed further)
density_to_t <- function(x) {
  old <- if (x <= 0) 100 + 2 * x else 100 + x
  old / 100
}

scale_mod <- function(target, t) max(0, 100 + (target - 100) * t)
scale_amt <- function(target, t) min(100, max(0, target * t))

long_side <- function(img) {
  i <- image_info(img)
  max(i$width, i$height)
}

# ---- Mixing ---------------------------------------------------------------
# t in (0, 1)  -> ordinary blend of photo and effect
# t > 1        -> extrapolates past the effect  (pushed further)
# t < 0        -> extrapolates away from it     (opposite effect)
# ImageMagick's "mathematics" compose computes  b*effect + c*photo  (clamped).
mix_images <- function(orig, effect, t) {
  if (t == 0) return(orig)
  if (t == 1) return(effect)
  if (t > 0 && t < 1) {
    pct <- t * 100
    return(image_composite(orig, effect, operator = "blend",
                           compose_args = paste0(pct, ",", 100 - pct)))
  }
  image_composite(orig, effect, operator = "mathematics",
                  compose_args = paste0("0,", t, ",", 1 - t, ",0"))
}

# ---- Contrast, with fractional strength -----------------------------------
# magick's image_contrast() only knows whole steps (and a negative step
# actually *raises* contrast), which made the old slider jump. Positive
# amounts repeat the step and blend the remainder; negative amounts blend
# toward mid-grey, which flattens ("fades") the photo.
adjust_contrast <- function(img, amount) {
  if (abs(amount) < 0.05) return(img)
  if (amount < 0) return(image_colorize(img, min(100, 14 * abs(amount)), "gray50"))
  n <- floor(amount)
  frac <- amount - n
  out <- img
  for (i in seq_len(n)) out <- image_contrast(out, sharpen = 1)
  if (frac > 0.05) out <- mix_images(out, image_contrast(out, sharpen = 1), frac)
  out
}

# Colour on the opposite side of the wheel, used for the "opposite" tint.
complement_colour <- function(col) {
  rgb <- grDevices::col2rgb(col)[, 1]
  grDevices::rgb(255 - rgb[1], 255 - rgb[2], 255 - rgb[3], maxColorValue = 255)
}

# ---- Tone filters: one table, one function --------------------------------
# bright / sat      modulate targets (100 = unchanged)
# contrast          contrast steps at the normal look
# push_contrast     extra contrast steps per unit of t above 1 (so filters whose
#                   saturation is already 0, like Noir, still push further)
# tint, tint_amt    colour overlay (percent at the normal look)
tone_specs <- list(
  Sepia     = list(sat = 40, tint = "sienna", tint_amt = 30),
  Noir      = list(sat = 0, push_contrast = 2.5),
  Duotone   = list(sat = 0, tint = "deepskyblue", tint_amt = 50),
  Vintage   = list(bright = 95, sat = 70, tint = "brown", tint_amt = 15),
  Warm      = list(bright = 105, sat = 120, tint = "orange", tint_amt = 10),
  Cool      = list(bright = 105, sat = 90, tint = "skyblue", tint_amt = 15),
  Dramatic  = list(bright = 90, sat = 115, contrast = 2),
  Bright    = list(bright = 125, sat = 110),
  Moody     = list(bright = 75, sat = 90, contrast = 1),
  Cyanotype = list(sat = 0, tint = "#1e5a8a", tint_amt = 60),
  Sunset    = list(bright = 105, sat = 135, tint = "#ff6a3d", tint_amt = 22)
)

apply_tone <- function(img, spec, t) {
  bright <- spec$bright %||% 100
  sat    <- spec$sat %||% 100
  out <- img
  if (bright != 100 || sat != 100) {
    out <- image_modulate(out, brightness = scale_mod(bright, t),
                          saturation = scale_mod(sat, t))
  }
  contrast <- (spec$contrast %||% 0) * t +
    (spec$push_contrast %||% 0) * max(0, t - 1)
  out <- adjust_contrast(out, contrast)
  if (!is.null(spec$tint)) {
    amt <- spec$tint_amt * t
    col <- if (amt >= 0) spec$tint else complement_colour(spec$tint)
    amt <- min(100, abs(amt))
    if (amt > 0) out <- image_colorize(out, amt, col)
  }
  out
}

# ---- Faded: a matte fade ----------------------------------------------------
# Blends toward grey, which lifts the blacks and flattens the tones (about 26%
# less contrast at the normal look, about 50% pushed further).
# The opposite side (t < 0) only deepens colour and brightness. It never adds
# contrast steps, so the slider never "plays the contrast game" in either direction.
apply_faded <- function(img, t) {
  if (t > 0) {
    out <- image_modulate(img, brightness = scale_mod(105, t), saturation = scale_mod(80, t))
    return(image_colorize(out, min(80, 26 * t), "gray60"))
  }
  image_modulate(img, brightness = 100 + 8 * t, saturation = 100 - 25 * t)
}

# ---- Effect filters (size-aware) ------------------------------------------
# Every pixel-based parameter is a fraction of the image's long side, so the
# 520px thumbnail, the 1400px preview and the full-size download all look alike.

apply_vignette <- function(img, t) {
  info <- image_info(img)
  mask <- image_blank(info$width, info$height, pseudo_image = "radial-gradient:white-black")
  once <- image_composite(img, mask, operator = "multiply")
  if (t <= 1) return(mix_images(img, once, t))   # t < 0 lightens the edges instead
  # pushed further: apply the mask a second time (extrapolating would blow out the corners)
  mix_images(once, image_composite(once, mask, operator = "multiply"), min(1, t - 1))
}

# Grey noise generated on a grid of at most 1200px and stretched to the photo,
# then overlaid. Same grain size relative to the frame at any resolution.
# Grain has no opposite, so it only applies for t > 0.
apply_grain <- function(img, t) {
  if (t <= 0) return(img)
  info <- image_info(img)
  sc <- min(1, 1200 / max(info$width, info$height))
  w <- max(1, round(info$width * sc))
  h <- max(1, round(info$height * sc))
  noise <- image_blank(w, h, "gray50")
  noise <- image_noise(noise, noisetype = "gaussian")
  noise <- image_modulate(noise, saturation = 0)
  if (sc < 1) noise <- image_resize(noise, paste0(info$width, "x", info$height, "!"))
  mix_images(img, image_composite(img, noise, operator = "overlay"), t)
}

apply_negative <- function(img, t) mix_images(img, image_negate(img), t)

apply_poster <- function(img, t) {
  if (t <= 0) return(img)
  image_quantize(img, max = min(256, max(2, round(8 / t))), colorspace = "sRGB")
}

apply_emboss <- function(img, t) {
  sigma <- max(0.5, long_side(img) / 1000)
  mix_images(img, image_emboss(img, radius = 0, sigma = sigma), t)
}

apply_sketch <- function(img, t) {
  sigma <- max(0.5, long_side(img) / 1000)
  mix_images(img, image_charcoal(img, radius = 0, sigma = sigma), t)
}

# Higher density = chunkier pixels (fewer cells along the long side).
apply_pixelate <- function(img, t) {
  if (t <= 0) return(img)
  info <- image_info(img)
  cells <- max(8, round(48 / t))
  if (cells >= max(info$width, info$height)) return(img)
  small <- image_sample(img, paste0(cells, "x", cells))
  image_sample(small, paste0(info$width, "x", info$height, "!"))
}

# Positive = blur, negative = sharpen (an unsharp mask: the photo pushed away
# from its own blur). magick has no image_sharpen(), which the old code called.
apply_blur <- function(img, t) {
  blurred <- image_blur(img, radius = 0,
                        sigma = max(0.1, 0.004 * long_side(img) * abs(t)))
  if (t > 0) blurred else mix_images(blurred, img, 1 + 2 * abs(t))
}

# ---- Registry + dispatcher (preview, thumbnails and download share it) ----
filter_names <- c(
  "Original", "Sepia", "Vignette", "Grain", "Faded", "Noir", "Duotone",
  "Vintage", "Warm", "Cool", "Dramatic", "Bright", "Moody", "Negative",
  "Poster", "Blur", "Cyanotype", "Sunset", "Emboss", "Sketch", "Pixelate"
)

# Filters with no meaningful "opposite": below 0 they return the original photo.
no_opposite <- c("Grain", "Poster", "Pixelate")

# One plain function, no closures: it can be copied into background workers as text.
apply_filter_by_name <- function(img, name, t = 1) {
  if (identical(name, "Original") || t == 0) return(img)
  if (!is.null(tone_specs[[name]])) return(apply_tone(img, tone_specs[[name]], t))
  switch(name,
    Faded    = apply_faded(img, t),
    Vignette = apply_vignette(img, t),
    Grain    = apply_grain(img, t),
    Negative = apply_negative(img, t),
    Poster   = apply_poster(img, t),
    Blur     = apply_blur(img, t),
    Emboss   = apply_emboss(img, t),
    Sketch   = apply_sketch(img, t),
    Pixelate = apply_pixelate(img, t),
    stop("Unknown filter: ", name, call. = FALSE)
  )
}

# ---- Layers (stacked filters) ---------------------------------------------
# A layer is list(filter, density). Layers are applied in order, then the
# filter that is still being edited.
mk_layer <- function(filter, density) list(filter = filter, density = as.numeric(density))

apply_layers <- function(img, layers, filter = "Original", density = 0) {
  for (l in layers) img <- apply_filter_by_name(img, l$filter, density_to_t(l$density))
  apply_filter_by_name(img, filter, density_to_t(density))
}


# ---- R/utils.R ----
# =========================================================
# IMAGE LOADING / ENCODING HELPERS
# =========================================================

WORK_SIDE <- 1400L   # long side of the copy used for the live preview
THUMB_SIDE <- 520L   # long side of the copy used for archive tiles
# uploads larger than this are scaled down (memory guard; lower on small hosted servers)
MAX_SIDE <- if (isTRUE(getOption("retrolens.hosted", FALSE))) 3000L else 6000L

# Server-side file-type check by magic bytes. The browser's `accept` filter is
# only a hint; this runs before ImageMagick ever sees the file.
detect_image_type <- function(path) {
  b <- readBin(path, "raw", n = 12L)
  if (length(b) < 12L) return(NA_character_)
  if (identical(b[1:3], as.raw(c(0xFF, 0xD8, 0xFF)))) return("jpeg")
  if (identical(b[1:8], as.raw(c(0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A)))) return("png")
  if (identical(b[1:4], charToRaw("RIFF")) && identical(b[9:12], charToRaw("WEBP"))) return("webp")
  NA_character_
}

# Reads an upload into a list(full, work, id):
#   full  the photo, upright, flattened, at most MAX_SIDE px  (used for Download)
#   work  a WORK_SIDE px copy                                 (used for everything live)
# Throws a friendly error (class "photo_error") instead of crashing the session.
load_photo <- function(path) {
  fail <- function(msg) stop(structure(class = c("photo_error", "error", "condition"),
                                       list(message = msg, call = NULL)))
  type <- tryCatch(detect_image_type(path), error = function(e) NA_character_)
  if (is.na(type)) fail("Only PNG, JPG or WebP photos work.")
  img <- tryCatch(image_read(path), error = function(e) NULL)
  if (is.null(img) || length(img) < 1L) fail("That file could not be read as a photo.")
  img <- img[1]                                           # first frame only
  img <- image_orient(img)                                # honour EXIF rotation (phone photos)
  img <- image_background(img, "white", flatten = TRUE)   # transparent PNGs: no black patches
  img <- image_convert(img, colorspace = "sRGB", depth = 8)  # half the memory of 16-bit
  img <- image_resize(img, paste0(MAX_SIDE, "x", MAX_SIDE, ">"))
  list(
    full = img,
    work = image_resize(img, paste0(WORK_SIDE, "x", WORK_SIDE, ">")),
    id   = unname(tools::md5sum(path)),
    path = path        # kept so a background worker can re-read the upload
  )
}

rotate_flip <- function(img, rotation, flipped) {
  if (rotation != 0) img <- image_rotate(img, rotation)
  if (flipped) img <- image_flop(img)
  img
}

# JPEG data URI for the browser (about 10x smaller than the old PNG one).
encode_uri <- function(img, quality = 86) {
  raw <- image_write(img, path = NULL, format = "jpeg", quality = quality)
  paste0("data:image/jpeg;base64,", base64enc::base64encode(raw))
}

# "my holiday photo.PNG" + "Sepia" -> "my-holiday-photo-sepia.png"
download_name <- function(original, filter, ext) {
  stem <- tools::file_path_sans_ext(basename(original %||% "photo"))
  stem <- gsub("[^A-Za-z0-9_-]+", "-", stem)
  stem <- gsub("^-+|-+$", "", stem)
  if (!nzchar(stem)) stem <- "photo"
  tolower(paste0(stem, "-", filter, ".", ext))
}

# Every exported file (Download and the REST API) goes through here. image_strip()
# drops the original photo's hidden data - GPS position, camera model, date, comments -
# so an edited photo can be shared without leaking where it was taken. Colours are
# unaffected: load_photo() already converted the pixels to sRGB.
write_download <- function(img, file, format = c("png", "jpeg", "webp")) {
  format <- match.arg(format)
  img <- image_strip(img)
  image_write(img, path = file, format = format,
              quality = switch(format, png = NULL, jpeg = 93, webp = 90))
}

# ---- Export (used by Download, in-process or in a background worker) -------
# spec: list(path, layers, filter, density, rot, flip, format)
# `img` is the full-size photo when the caller already has it; a worker passes
# NULL and the photo is re-read from spec$path.
render_export <- function(spec, out, img = NULL) {
  if (is.null(img)) img <- load_photo(spec$path)$full
  img <- rotate_flip(img, spec$rot, spec$flip)
  img <- apply_layers(img, spec$layers, spec$filter, spec$density)
  write_download(img, out, spec$format)
  invisible(out)
}

# ---- Looks: a whole edit as a short, URL-safe code -------------------------
# A "look" = stacked layers + the filter being edited + density + rotation + mirror.
# It is what "Copy share link", "Save look" and the API's `look=` parameter carry.
MAX_LAYERS <- 6L

blank_state <- function() list(layers = list(), filter = "Original", density = 0, rot = 0, flip = FALSE)

encode_look <- function(st) {
  json <- jsonlite::toJSON(list(
    v = 1L,
    layers = lapply(st$layers, function(l) list(filter = l$filter, density = l$density)),
    filter = st$filter, density = st$density, rot = st$rot, flip = isTRUE(st$flip)
  ), auto_unbox = TRUE)
  chartr("+/=", "-_.", base64enc::base64encode(charToRaw(as.character(json))))
}

# Returns a clean state list, or NULL if the code is not a valid look. Everything
# in it is checked, because the code can come from a URL or from anyone's browser.
decode_look <- function(code) {
  tryCatch({
    if (!is.character(code) || length(code) != 1L || is.na(code) || nchar(code) > 3000L) return(NULL)
    x <- jsonlite::fromJSON(rawToChar(base64enc::base64decode(chartr("-_.", "+/=", code))),
                            simplifyVector = FALSE)
    ok_filter <- function(f) is.character(f) && length(f) == 1L && f %in% filter_names
    ok_num <- function(d) is.numeric(d) && length(d) == 1L && is.finite(d)
    clamp <- function(d) as.numeric(max(-100, min(100, round(d))))
    if (!ok_filter(x$filter) || !ok_num(x$density)) return(NULL)
    lays <- list()
    for (l in x$layers %||% list()) {
      if (!is.list(l) || !ok_filter(l$filter) || !ok_num(l$density)) return(NULL)
      lays[[length(lays) + 1L]] <- mk_layer(l$filter, clamp(l$density))
    }
    if (length(lays) > MAX_LAYERS) return(NULL)
    rot <- if (ok_num(x$rot) && x$rot %in% c(0, 90, 180, 270)) as.numeric(x$rot) else 0
    list(layers = lays, filter = x$filter, density = clamp(x$density), rot = rot, flip = isTRUE(x$flip))
  }, error = function(e) NULL)
}

# ---- Background workers ----------------------------------------------------
# A fresh R worker does not have this app's functions. Rather than rely on
# automatic global detection, the worker gets the filter/export code as text.
WORKER_OBJECTS <- c(
  "%||%", "density_to_t", "scale_mod", "scale_amt", "long_side", "mix_images",
  "adjust_contrast", "complement_colour", "tone_specs", "apply_tone", "apply_faded",
  "apply_vignette", "apply_grain", "apply_negative", "apply_poster", "apply_emboss",
  "apply_sketch", "apply_pixelate", "apply_blur", "filter_names", "no_opposite",
  "apply_filter_by_name", "mk_layer", "apply_layers", "WORK_SIDE", "THUMB_SIDE", "MAX_SIDE",
  "detect_image_type", "load_photo", "rotate_flip", "write_download", "render_export"
)
.worker_cache <- new.env()
worker_bootstrap <- function() {
  if (is.null(.worker_cache$src)) {
    .worker_cache$src <- paste(vapply(WORKER_OBJECTS, function(n) {
      paste0("`", n, "` <- ", paste(deparse(get(n, inherits = TRUE)), collapse = "\n"))
    }, character(1)), collapse = "\n\n")
  }
  .worker_cache$src
}

# Can this session render in the background? (needs the optional future + promises)
# Set options(retrolens.async = FALSE) to force the in-process path; hosted mode does too.
async_available <- function() {
  isTRUE(getOption("retrolens.async", TRUE)) &&
    !isTRUE(getOption("retrolens.hosted", FALSE)) &&
    requireNamespace("future", quietly = TRUE) && requireNamespace("promises", quietly = TRUE)
}


# ---- R/api.R ----
# =========================================================
# REST API  (optional; needs the `plumber` package)
#
#   Run it in its own R session:
#     source("app.R"); retro_lens_api()        # http://127.0.0.1:8000
#
#   GET  /health
#   GET  /filters
#   POST /filter?name=Sepia&density=0&format=jpeg      body = the raw image bytes
#   POST /filter?look=<code from "Copy share link">    apply a whole saved/shared look
#
#   curl -X POST --data-binary @photo.jpg -H "Content-Type: application/octet-stream" \
#        "http://127.0.0.1:8000/filter?name=Noir&density=20" -o out.jpg
#
#   It reuses exactly the same filter code as the app. It listens on localhost only
#   unless you pass host = "0.0.0.0" (add authentication before exposing it).
# =========================================================

retro_lens_api <- function(host = "127.0.0.1", port = 8000L, max_mb = 20, run = TRUE) {
  if (!requireNamespace("plumber", quietly = TRUE)) {
    stop('The API needs plumber:  install.packages("plumber")', call. = FALSE)
  }
  mime <- c(jpeg = "image/jpeg", png = "image/png", webp = "image/webp")

  # Every response, errors included, is written by hand so the image bytes are never
  # passed through a JSON serializer.
  reply <- function(res, status, body, type) {
    res$status <- status
    res$setHeader("Content-Type", type)
    res$body <- body
    res
  }
  fail <- function(res, status, msg) {
    reply(res, status, as.character(jsonlite::toJSON(list(error = msg), auto_unbox = TRUE)),
          "application/json")
  }

  handler <- function(req, res, name = NULL, density = "0", format = "jpeg", look = "") {
    body <- req$body
    if (!is.raw(body) || length(body) == 0L) {
      return(fail(res, 400, "Send the image as the raw request body (Content-Type: application/octet-stream)."))
    }
    if (length(body) > max_mb * 1024^2) return(fail(res, 413, paste0("Image larger than ", max_mb, " MB.")))
    if (!format %in% names(mime)) return(fail(res, 400, "format must be jpeg, png or webp."))

    if (nzchar(look)) {
      st <- decode_look(look)
      if (is.null(st)) return(fail(res, 400, "That look code is not valid."))
    } else {
      d <- suppressWarnings(as.numeric(density))
      if (is.null(name) || !name %in% filter_names) {
        return(fail(res, 400, paste0("name must be one of: ", paste(filter_names, collapse = ", "))))
      }
      if (is.na(d) || d < -100 || d > 100) return(fail(res, 400, "density must be between -100 and 100."))
      st <- list(layers = list(), filter = name, density = d, rot = 0, flip = FALSE)
    }

    tmp <- tempfile(); out <- tempfile(fileext = paste0(".", format))
    on.exit(unlink(c(tmp, out)), add = TRUE)
    writeBin(body, tmp)
    photo <- tryCatch(load_photo(tmp), photo_error = function(e) e, error = function(e) e)
    if (inherits(photo, "error")) return(fail(res, 400, conditionMessage(photo)))

    spec <- c(st, list(format = format))
    render_export(spec, out, img = photo$full)
    reply(res, 200L, readBin(out, "raw", file.size(out)), mime[[format]])
  }

  pr <- plumber::pr()
  pr <- plumber::pr_get(pr, "/health", function() list(status = "ok"),
                       serializer = plumber::serializer_unboxed_json())
  pr <- plumber::pr_get(pr, "/filters", function() {
    list(filters = filter_names,
         density = "-100 .. 100 (0 = the filter's normal look, -50 = the original photo)")
  }, serializer = plumber::serializer_unboxed_json())
  pr <- plumber::pr_post(pr, "/filter", handler, parsers = "octet")
  if (run) plumber::pr_run(pr, host = host, port = as.integer(port)) else pr
}

# =============================================================================
# PINNED VERSIONS WITH renv  (optional - run once, from the folder that holds app.R)
# =============================================================================
lock_dependencies <- function(project = getwd()) {
  if (!requireNamespace("renv", quietly = TRUE)) {
    stop('Install renv first:  install.packages("renv")', call. = FALSE)
  }
  if (!file.exists(file.path(project, "app.R"))) {
    stop("Run this from the folder that contains app.R (or pass project = \"that/folder\").",
         call. = FALSE)
  }
  renv::init(project = project, restart = FALSE)     # scans app.R for the packages it uses
  renv::snapshot(project = project, prompt = FALSE)  # writes renv.lock
  message("renv.lock written to ", normalizePath(project),
          ".\nOn another machine: open this folder in R and run  renv::restore()")
  invisible(file.path(project, "renv.lock"))
}



