# Small inline SVG icons (currentColor, so they follow the theme)
svg_icon <- function(paths, size = 14, stroke = 2) {
  HTML(sprintf(paste0("<svg viewBox='0 0 24 24' width='%d' height='%d' fill='none' stroke='currentColor' ",
                      "stroke-width='%s' stroke-linecap='round' stroke-linejoin='round' ",
                      "aria-hidden='true' focusable='false'>%s</svg>"), size, size, stroke, paths))
}
