# ---- the three-line menu: a main list that opens sub-views inside one panel ----
# One row of the main list. `view` opens a sub-view; `action` runs something
# (see the menu code in www/app.js). `label_for_readers` replaces the spoken name.
menu_nav <- function(label, icon, view = NULL, action = NULL, label_for_readers = NULL) {
  tags$button(type = "button", class = "menu-item menu-nav",
              `data-open-view` = view, `data-menu-action` = action,
              `aria-label` = label_for_readers,
              span(class = "menu-ico", icon), span(class = "menu-label", label),
              span(class = "menu-go", if (is.null(action)) icon_next else icon_out))
}

# A sub-view: back button + title, then its own content
menu_view <- function(name, title, ...) {
  div(class = "menu-view", `data-view` = name, hidden = NA,
      div(class = "menu-head",
          tags$button(type = "button", class = "menu-back", `data-menu-back` = NA,
                      `aria-label` = "Back to the menu", icon_back),
          span(class = "menu-head-title", title)),
      ...)
}

# Dark / Light rows
theme_row <- function(id, label, swatch, checked = FALSE) {
  tags$button(type = "button", class = "menu-item", role = "radio",
              `data-theme-choice` = id, `aria-checked` = tolower(as.character(checked)),
              span(class = paste("swatch", swatch)), label,
              span(class = "menu-check", HTML("&#10003;")))
}

# One colour combo: two round chips and the pair's name. a / b = c(id, name, background, ink)
combo_row <- function(a, b) {
  chip <- function(x) {
    tags$button(type = "button", class = "chip", role = "radio",
                `data-theme-choice` = x[1], `aria-checked` = "false",
                `aria-label` = x[2], title = x[2],
                style = sprintf("--chip-bg:%s;--chip-ink:%s", x[3], x[4]))
  }
  div(class = "combo", chip(a), chip(b),
      span(class = "combo-name", a[2], tags$br(), b[2]))
}

# One entry of the Download format menu (see the .dl-menu markup in R/ui.R)
dl_option <- function(value, ext, hint, selected = FALSE) {
  tags$button(type = "button", class = "dl-opt", role = "option", tabindex = "-1",
              `data-value` = value, `aria-selected` = if (selected) "true" else "false",
              span(class = "dl-opt-ext", ext), span(class = "dl-opt-hint", hint),
              span(class = "dl-opt-check", icon_check))
}

# One row of the keyboard-shortcut legend
key_row <- function(keys, what) {
  div(class = "keys-row",
      span(class = "keys-cap", lapply(keys, tags$kbd)),
      span(what))
}

logo_svg <- HTML(paste0(
  "<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='1.6' ",
  "stroke-linecap='round' stroke-linejoin='round' aria-hidden='true'>",
