# Dark theme uses the original photo (black background + "lighten" blend); the
# light theme uses the same flower with its background removed (transparent
# WebP). Both are swapped by CSS. Only the hero image loads eagerly.
art_img <- function(file, class, eager = FALSE, ...) {
  cut <- sub("\\.jpg$", "-cut.webp", file)
  lazy <- if (eager) NULL else "lazy"
  tagList(
    tags$img(class = paste("art only-dark", class), src = paste0("art/", file),
             alt = "", `aria-hidden` = "true", loading = lazy, decoding = "async", ...),
    tags$img(class = paste("art only-light", class), src = paste0("art/", cut),
             alt = "", `aria-hidden` = "true", loading = lazy, decoding = "async", ...)
  )
}

step_item <- function(n, title, body) {
  div(class = "step reveal",
      div(class = "step-rail", span(class = "step-n", n), tags$i()),
      div(class = "step-body", tags$h3(title), tags$p(body)))
}

# The archive grid is static HTML: 21 tiles that show the pre-rendered samples
# until a photo is uploaded. The server then streams each tile's thumbnail in
# (see R/server.R), so the grid never re-renders and the page never jumps.
filter_grid <- function() {
  tiles <- lapply(seq_along(filter_names), function(i) {
    fn <- filter_names[i]
    tags$div(
      class = "filter-thumb is-empty",
      `data-filter` = fn, role = "button", tabindex = "0",
      tags$img(src = sprintf("art/sample-%02d.jpg", i), `data-sample` = sprintf("art/sample-%02d.jpg", i),
               alt = paste(fn, "sample"),
               draggable = "false", loading = "lazy", decoding = "async"),
      span(class = "tile-sample", "Sample"),
      div(class = "tile-shade"),
      div(class = "tile-meta",
          span(class = "thumb-label", fn),
          span(class = "tile-idx", sprintf("%02d", i)))
    )
  })
  div(id = "filter_thumbs", tags$div(class = "bento", tiles))
}


# ---- page styles, scroll engine and behaviour (embedded) ----

APP_CSS <- r"---(
/* Self-hosted fonts (Inter, Playfair Display) - OFL licensed, via @fontsource */
@font-face{font-family:'Inter';font-style:normal;font-weight:400;font-display:swap;src:url(art/inter-latin-400-normal.woff2) format('woff2')}
@font-face{font-family:'Inter';font-style:normal;font-weight:500;font-display:swap;src:url(art/inter-latin-500-normal.woff2) format('woff2')}
@font-face{font-family:'Inter';font-style:normal;font-weight:600;font-display:swap;src:url(art/inter-latin-600-normal.woff2) format('woff2')}
@font-face{font-family:'Inter';font-style:normal;font-weight:700;font-display:swap;src:url(art/inter-latin-700-normal.woff2) format('woff2')}
@font-face{font-family:'Playfair Display';font-style:normal;font-weight:400;font-display:swap;src:url(art/playfair-display-latin-400-normal.woff2) format('woff2')}
@font-face{font-family:'Playfair Display';font-style:italic;font-weight:400;font-display:swap;src:url(art/playfair-display-latin-400-italic.woff2) format('woff2')}
@font-face{font-family:'Playfair Display';font-style:italic;font-weight:500;font-display:swap;src:url(art/playfair-display-latin-500-italic.woff2) format('woff2')}

      :root {
        color-scheme: dark;
        --bg: #0a0a0a;
        --surface: #121212;
        --sunken: #0d0d0d;
        --line: rgba(255, 255, 255, 0.10);
        --line-strong: rgba(255, 255, 255, 0.22);
        --text: #f4f4f4;
        --muted: #8e8e8e;
        --soft: #bdbdbd;
        --pill: #ffffff;
        --pill-ink: #0a0a0a;
        --rose: #f4a3b5;
        --glow: rgba(244, 163, 181, 0.10);
        /* surfaces that were hard-coded, now themeable */
        --fill: rgba(255, 255, 255, 0.05);
        --fill-2: rgba(255, 255, 255, 0.08);
        --fill-3: rgba(255, 255, 255, 0.14);
        --line-hi: rgba(255, 255, 255, 0.4);
        --pill-hover: #e6e6e6;
        --pill-active: #d8d8d8;
        --glass: rgba(10, 10, 10, 0.72);
        --glass-strong: rgba(18, 18, 18, 0.88);
        --overlay: rgba(10, 10, 10, 0.93);
        --track: #262626;
        --track-2: #2a2a2a;
        --kbd: #1e1e1e;
        --kbd-edge: rgba(255, 255, 255, 0.10);
        --ghost: rgba(255, 255, 255, 0.028);
        --tile-a: #181818;
        --tile-b: #0d0d0d;
        --r-card: 24px;
        --r-inner: 16px;
        --sans: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
        --serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
      }

      /* ---- Light theme (switched from the menu; saved in localStorage) ---- */
      html[data-theme="light"] {
        color-scheme: light;
        --bg: #f6f3ee;
        --surface: #ffffff;
        --sunken: #efebe5;
        --line: rgba(20, 20, 20, 0.11);
        --line-strong: rgba(20, 20, 20, 0.24);
        --text: #161616;
        --muted: #6a6762;
        --soft: #3d3b38;
        --pill: #161616;
        --pill-ink: #ffffff;
        --rose: #c9456b;
        --fill: rgba(20, 20, 20, 0.05);
        --fill-2: rgba(20, 20, 20, 0.07);
        --fill-3: rgba(20, 20, 20, 0.12);
        --line-hi: rgba(20, 20, 20, 0.4);
        --pill-hover: #343230;
        --pill-active: #4a4845;
        --glass: rgba(246, 243, 238, 0.78);
        --glass-strong: rgba(255, 255, 255, 0.92);
        --overlay: rgba(246, 243, 238, 0.95);
        --track: #dcd7d0;
        --track-2: #cfc9c1;
        --kbd: #f1eee9;
        --kbd-edge: rgba(20, 20, 20, 0.14);
        --ghost: rgba(20, 20, 20, 0.045);
        --tile-a: #ffffff;
        --tile-b: #f1ede7;
      }
      /* ---- Colour combos: each pair gives two themes (either colour as the page). Only 4 seeds per theme,
         everything else is derived from them below. ---- */
      html[data-theme="buttermilk"] { --c-bg: #FFF2BA; --c-ink: #0F3C65; --c-accent: #0F3C65; --c-scheme: light; }
      html[data-theme="midnight"] { --c-bg: #0F3C65; --c-ink: #FFF2BA; --c-accent: #FFF2BA; --c-scheme: dark; }
      html[data-theme="seashell"] { --c-bg: #FFF7EF; --c-ink: #5A2E1B; --c-accent: #FF844D; --c-scheme: light; --c-pill: #FF844D; --c-pill-ink: #3A1807; }
      html[data-theme="tangerine"] { --c-bg: #FF844D; --c-ink: #3A1807; --c-accent: #FFF7EF; --c-scheme: light; }
      html[data-theme="lavender"] { --c-bg: #CCC3EB; --c-ink: #4E3B53; --c-accent: #4E3B53; --c-scheme: light; }
      html[data-theme="plum"] { --c-bg: #4E3B53; --c-ink: #CCC3EB; --c-accent: #CCC3EB; --c-scheme: dark; }
      html[data-theme="marigold"] { --c-bg: #FFE08C; --c-ink: #713443; --c-accent: #E36887; --c-scheme: light; --c-pill: #E36887; --c-pill-ink: #3D0F1F; }
      html[data-theme="blush"] { --c-bg: #E36887; --c-ink: #3D0F1F; --c-accent: #FFE08C; --c-scheme: light; }
      html[data-theme="butternut"] { --c-bg: #FFA175; --c-ink: #5C0702; --c-accent: #5C0702; --c-scheme: light; }
      html[data-theme="cherry"] { --c-bg: #5C0702; --c-ink: #FFA175; --c-accent: #FFA175; --c-scheme: dark; }
      html[data-theme="olive"] { --c-bg: #4D694E; --c-ink: #FFF3D5; --c-accent: #FFF3D5; --c-scheme: dark; }
      html[data-theme="beige"] { --c-bg: #FFF3D5; --c-ink: #4D694E; --c-accent: #4D694E; --c-scheme: light; }
      html[data-pal] {
        color-scheme: var(--c-scheme);
        --bg: var(--c-bg);
        --surface: color-mix(in srgb, var(--c-bg) 93%, var(--c-ink));
        --sunken: color-mix(in srgb, var(--c-bg) 89%, var(--c-ink));
        --line: color-mix(in srgb, var(--c-ink) 16%, transparent);
        --line-strong: color-mix(in srgb, var(--c-ink) 32%, transparent);
        --line-hi: color-mix(in srgb, var(--c-ink) 42%, transparent);
        --text: var(--c-ink);
        --soft: color-mix(in srgb, var(--c-ink) 84%, var(--c-bg));
        --muted: color-mix(in srgb, var(--c-ink) 64%, var(--c-bg));
        --pill: var(--c-pill, var(--c-ink));
        --pill-ink: var(--c-pill-ink, var(--c-bg));
        --rose: var(--c-accent);
        --glow: color-mix(in srgb, var(--c-accent) 16%, transparent);
        --fill: color-mix(in srgb, var(--c-ink) 6%, transparent);
        --fill-2: color-mix(in srgb, var(--c-ink) 9%, transparent);
        --fill-3: color-mix(in srgb, var(--c-ink) 14%, transparent);
        --pill-hover: color-mix(in srgb, var(--pill) 84%, var(--c-bg));
        --pill-active: color-mix(in srgb, var(--pill) 68%, var(--c-bg));
        --glass: color-mix(in srgb, var(--c-bg) 78%, transparent);
        --glass-strong: color-mix(in srgb, var(--c-bg) 94%, transparent);
        --overlay: color-mix(in srgb, var(--c-bg) 96%, transparent);
        --track: color-mix(in srgb, var(--c-ink) 14%, var(--c-bg));
        --track-2: color-mix(in srgb, var(--c-ink) 22%, var(--c-bg));
        --kbd: color-mix(in srgb, var(--c-ink) 8%, var(--c-bg));
        --kbd-edge: color-mix(in srgb, var(--c-ink) 18%, transparent);
        --ghost: color-mix(in srgb, var(--c-ink) 5%, transparent);
        --tile-a: color-mix(in srgb, var(--c-ink) 4%, var(--c-bg));
        --tile-b: color-mix(in srgb, var(--c-ink) 11%, var(--c-bg));
      }
      html[data-pal] .pin-art.on { opacity: 0.8; }
      /* flowers: dark theme shows the original photos, light theme the background-free cut-outs */
      html[data-theme="light"] .only-dark, html[data-pal] .only-dark,
      html:not([data-theme="light"]):not([data-pal]) .only-light { display: none !important; }
      .art.only-light { mix-blend-mode: normal; }
      html[data-theme="light"] .pin-art.on { opacity: 0.8; }
      /* sticky makes its own stacking context, so give it a backdrop for the blend modes to work against */
      .process.is-pinned .pin { background: var(--bg); }
      html[data-theme="light"] #toast { box-shadow: 0 10px 40px rgba(0, 0, 0, 0.18); }
      html[data-theme="light"] #dock { box-shadow: 0 16px 50px rgba(0, 0, 0, 0.18); }
      html.theme-anim *, html.theme-anim *::before, html.theme-anim *::after {
        transition: background-color 0.45s ease, color 0.45s ease, border-color 0.45s ease, fill 0.45s ease, stroke 0.45s ease, box-shadow 0.45s ease !important;
      }

      ::selection { background: var(--pill); color: var(--pill-ink); }

      *:focus-visible {
        outline: 2px solid var(--pill) !important;
        outline-offset: 3px;
      }

      html { background: var(--bg); }
      body {
        background:
          radial-gradient(900px 420px at 88% -8%, var(--glow), transparent 65%),
          var(--bg);
        font-family: var(--sans);
        font-size: 15px;
        line-height: 1.5;
        letter-spacing: 0;
        color: var(--text);
        min-height: 100vh;
        -webkit-font-smoothing: antialiased;
      }
      label, .control-label, button, .btn, input, select {
        font-family: var(--sans) !important;
      }

      /* ---- Page shell ---- */
      html { scroll-behavior: smooth; }
      .container-fluid { padding-left: 0; padding-right: 0; }
      .wrap {
        position: relative;
        max-width: 1320px;
        margin: 0 auto;
        padding: 0 32px;
      }
      .sec { position: relative; scroll-margin-top: 72px; }

      /* Headlines: tight bold sans, italic serif for the accent word */
      .display {
        margin: 0;
        font-family: var(--sans);
        font-weight: 700;
        line-height: 0.98;
        letter-spacing: -0.045em;
        color: var(--text);
      }
      .display em {
        font-family: var(--serif);
        font-style: italic;
        font-weight: 400;
        letter-spacing: -0.02em;
        color: var(--soft);
      }
      .h-sec { font-size: clamp(2.1rem, 4.4vw, 3.2rem); line-height: 1.02; letter-spacing: -0.04em; }
      .sub { margin: 14px 0 0 0; max-width: 46ch; font-size: 15px; line-height: 1.55; color: var(--muted); }

      .eyebrow {
        display: inline-block;
        margin: 0;
        padding: 5px 12px;
        border: 1px solid var(--line-strong);
        border-radius: 999px;
        background: var(--fill);
        font-size: 10px;
        font-weight: 600;
        letter-spacing: 0.14em;
        text-transform: uppercase;
      }

      /* Flower art: the photos have black backgrounds, "lighten" lets the
         page colour win so the blooms look like they float on the page. */
      .art {
        position: absolute;
        z-index: 1;
        width: auto;
        max-width: none;
        mix-blend-mode: lighten;
        pointer-events: none;
        user-select: none;
        -webkit-user-drag: none;
      }

      /* ---- Pills ---- */
      a.pill, a.btn.btn-download-top {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 10px;
        padding: 11px 22px;
        background: var(--pill);
        color: var(--pill-ink) !important;
        border: 0;
        border-radius: 999px;
        box-shadow: none;
        font-weight: 600;
        font-size: 13px;
        line-height: 1;
        text-decoration: none !important;
        transition: transform 0.15s ease, background 0.15s ease;
      }
      a.pill.lg, a.btn.btn-download-top { padding: 15px 28px; font-size: 15px; }
      a.pill:hover, a.pill:focus,
      a.btn.btn-download-top:hover, a.btn.btn-download-top:focus {
        background: var(--pill-hover);
        color: var(--pill-ink) !important;
        transform: translateY(-1px);
      }
      a.pill:active, a.btn.btn-download-top:active, a.btn.btn-download-top:active:hover {
        background: var(--pill-active);
        color: var(--pill-ink) !important;
        transform: scale(0.97);
      }
      a.link-quiet {
        padding: 15px 8px;
        color: var(--text) !important;
        font-size: 14px;
        font-weight: 500;
        text-decoration: none !important;
        opacity: 0.85;
      }
      a.link-quiet:hover { opacity: 1; text-decoration: underline !important; text-underline-offset: 5px; }

      /* ---- Navigation ---- */
      .nav {
        position: fixed;
        top: 0; left: 0; right: 0;
        z-index: 800;
        border-bottom: 1px solid transparent;
        transition: background 0.2s ease, border-color 0.2s ease;
      }
      .nav.scrolled {
        background: var(--glass);
        -webkit-backdrop-filter: blur(14px);
        backdrop-filter: blur(14px);
        border-color: var(--line);
      }
      .nav-in {
        max-width: 1320px;
        height: 72px;
        margin: 0 auto;
        padding: 0 32px;
        display: grid;
        grid-template-columns: 1fr auto 1fr;
        align-items: center;
        gap: 24px;
      }
      a.logo {
        display: inline-flex;
        align-items: center;
        gap: 10px;
        justify-self: start;
        font-size: 18px;
        font-weight: 700;
        letter-spacing: -0.03em;
        color: var(--text) !important;
        text-decoration: none !important;
      }
      a.logo svg { width: 22px; height: 22px; color: var(--rose); }
      .nav-links { display: flex; gap: 34px; }
      .nav-links a {
        font-size: 13px;
        font-weight: 500;
        color: var(--soft);
        text-decoration: none !important;
        transition: color 0.15s ease;
      }
      .nav-links a:hover { color: var(--text); }
      .nav-right { justify-self: end; display: flex; align-items: center; gap: 10px; }
      .menu-wrap { position: relative; }
      .menu-btn {
        display: inline-flex; flex-direction: column; align-items: center; justify-content: center; gap: 4.5px;
        width: 42px; height: 42px; padding: 0;
        border: 1px solid var(--line-strong); border-radius: 50%;
        background: var(--fill); color: var(--text); cursor: pointer;
        transition: background 0.2s ease, border-color 0.2s ease;
      }
      .menu-btn:hover { background: var(--fill-2); border-color: var(--line-hi); }
      .menu-btn i {
        display: block; width: 16px; height: 1.6px; border-radius: 2px; background: currentColor;
        transition: transform 0.3s var(--ease-out, ease), opacity 0.2s ease;
      }
      .menu-btn[aria-expanded="true"] i:nth-child(1) { transform: translateY(6.1px) rotate(45deg); }
      .menu-btn[aria-expanded="true"] i:nth-child(2) { opacity: 0; }
      .menu-btn[aria-expanded="true"] i:nth-child(3) { transform: translateY(-6.1px) rotate(-45deg); }
      .menu-panel {
        position: absolute; top: calc(100% + 12px); right: 0; z-index: 900;
        width: 230px; padding: 10px;
        border: 1px solid var(--line-strong); border-radius: var(--r-inner);
        background: var(--glass-strong);
        -webkit-backdrop-filter: blur(16px); backdrop-filter: blur(16px);
        box-shadow: 0 18px 50px rgba(0, 0, 0, 0.35);
        opacity: 0; visibility: hidden; transform: translateY(-8px) scale(0.98); transform-origin: top right;
        transition: opacity 0.2s ease, transform 0.3s var(--ease-out, ease), visibility 0s linear 0.3s;
      }
      .menu-panel.open { opacity: 1; visibility: visible; transform: none; transition-delay: 0s; }
      .menu-item {
        display: flex; align-items: center; gap: 12px; width: 100%;
        padding: 10px; border: 0; border-radius: 10px; background: transparent;
        font-size: 14px; font-weight: 500; color: var(--text); text-align: left; cursor: pointer;
      }
      .menu-item:hover { background: var(--fill); }
      .menu-item[aria-checked="true"] { background: var(--fill-2); }
      .swatch {
        flex: none; width: 26px; height: 26px; border-radius: 50%; border: 1px solid var(--line-strong);
      }
      .swatch-dark { background: linear-gradient(135deg, #1c1c1c 55%, #f4a3b5 55%); }
      .swatch-light { background: linear-gradient(135deg, #f6f3ee 55%, #c9456b 55%); }
      .menu-check { margin-left: auto; opacity: 0; font-size: 14px; }
      .menu-panel { width: 300px; max-width: calc(100vw - 24px); max-height: min(78vh, 560px); overflow-y: auto; overscroll-behavior: contain; }
      .combo { display: flex; align-items: center; gap: 10px; padding: 6px 10px; border-radius: 10px; }
      .combo:hover { background: var(--fill); }
      .combo-name { font-size: 13px; font-weight: 500; color: var(--soft); line-height: 1.25; }
      .chip {
        position: relative; flex: none; width: 30px; height: 30px; padding: 0; cursor: pointer;
        border: 1px solid var(--line-strong); border-radius: 50%; background: var(--chip-bg);
        transition: transform 0.2s ease, box-shadow 0.2s ease;
      }
      .chip::after { content: ""; position: absolute; inset: 9px; border-radius: 50%; background: var(--chip-ink); }
      .chip:hover { transform: scale(1.08); }
      .chip[aria-checked="true"] { box-shadow: 0 0 0 2px var(--bg), 0 0 0 4px var(--text); }
      .menu-item[aria-checked="true"] .menu-check { opacity: 1; }

      /* ---- Menu: main list + sub-views (Themes, Colour combo, Shortcut keys) ---- */
      .menu-view[hidden] { display: none; }
      .menu-view:not([hidden]) { animation: menu-view-in .18s ease; }
      @keyframes menu-view-in { from { opacity: 0; transform: translateX(8px); } to { opacity: 1; transform: none; } }
      @media (prefers-reduced-motion: reduce) { .menu-view:not([hidden]) { animation: none; } }
      .menu-nav { gap: 12px; }
      .menu-ico {
        flex: none; display: inline-flex; align-items: center; justify-content: center;
        width: 30px; height: 30px; border: 1px solid var(--line-strong); border-radius: 50%; color: var(--text);
      }
      .menu-label { font-weight: 500; }
      .menu-go { margin-left: auto; display: inline-flex; color: var(--muted); transition: color .15s ease, transform .15s ease; }
      .menu-nav:hover .menu-go, .menu-nav:focus-visible .menu-go { color: var(--text); transform: translateX(2px); }
      .menu-head {
        display: flex; align-items: center; gap: 10px;
        margin: 0 0 8px; padding: 0 2px 10px; border-bottom: 1px solid var(--line);
      }
      .menu-back {
        flex: none; display: inline-flex; align-items: center; justify-content: center;
        width: 30px; height: 30px; padding: 0; cursor: pointer;
        border: 1px solid var(--line-strong); border-radius: 50%; background: transparent; color: var(--text);
        transition: background .15s ease;
      }
      .menu-back:hover { background: var(--fill-2); }
      .menu-head-title { font-size: 14px; font-weight: 600; color: var(--text); }
      .menu-keys { padding: 0 8px 4px; }

      /* ---- Hero ---- */
      .hero {
        min-height: min(100vh, 880px);
        padding: 160px 0 120px 0;
        overflow: hidden;
        background: radial-gradient(760px 520px at 86% 30%, var(--glow), transparent 70%);
      }
      .hero-copy { position: relative; z-index: 2; max-width: 640px; }
      .hero .display {
        margin-top: 22px;
        font-size: clamp(3.8rem, 9.5vw, 7.4rem);
      }
      .hero .display em { display: block; padding-bottom: 0.06em; }
      .hero-p {
        max-width: 40ch;
        margin: 26px 0 34px 0;
        font-size: 16px;
        line-height: 1.55;
        color: var(--soft);
      }
      .hero-cta { display: flex; flex-wrap: wrap; align-items: center; gap: 14px; }
      .art-hero {
        right: -1%;
        top: 0;
        height: 106%;
        -webkit-mask-image: linear-gradient(to bottom, #000 62%, transparent 94%),
                            linear-gradient(to right, transparent 0%, #000 22%);
        mask-image: linear-gradient(to bottom, #000 62%, transparent 94%),
                    linear-gradient(to right, transparent 0%, #000 22%);
        -webkit-mask-composite: source-in;
        mask-composite: intersect;
      }

      /* ---- Process ---- */
      .process { overflow: hidden; }
      .pin { position: relative; padding: 150px 0; }
      .art-left {
        left: -9%;
        top: 0;
        height: 100%;
        transform: scaleX(-1);
        -webkit-mask-image: linear-gradient(to bottom, transparent 0%, #000 20%, #000 80%, transparent 100%);
        mask-image: linear-gradient(to bottom, transparent 0%, #000 20%, #000 80%, transparent 100%);
      }
      .process-grid {
        z-index: 2;
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 80px;
        align-items: center;
      }
      .pin-art { opacity: 0; transition: opacity 1.1s ease, scale 1.6s cubic-bezier(0.16, 1, 0.3, 1); scale: 1.14; }
      .pin-art.on { opacity: 0.9; scale: 1; }
      .pin-art[data-step="1"] { transform: none; left: -4%; }
      .process-copy .h-sec { font-size: clamp(2.2rem, 4.6vw, 3.4rem); }
      .process-copy .sub { max-width: 34ch; }
      .steps { display: flex; flex-direction: column; gap: 40px; }
      .step { display: grid; grid-template-columns: 40px 1fr; gap: 20px; }
      .step:nth-child(even) { margin-left: 56px; }
      .step-rail { display: flex; flex-direction: column; align-items: center; gap: 10px; }
      .step-n {
        display: grid;
        place-items: center;
        width: 40px; height: 40px;
        border: 1px solid var(--line-strong);
        border-radius: 50%;
        background: var(--fill);
        font-size: 11px;
        font-weight: 600;
        color: var(--muted);
      }
      .step-rail i {
        display: block;
        flex: 1;
        width: 1px;
        min-height: 24px;
        background: linear-gradient(var(--line-strong), transparent);
      }
      .step-body h3 {
        margin: 6px 0 8px 0;
        font-size: 20px;
        font-weight: 600;
        letter-spacing: -0.02em;
        color: var(--text);
      }
      .step-body p { margin: 0; max-width: 38ch; font-size: 14px; line-height: 1.55; color: var(--muted); }

      /* ---- Studio (editor) ---- */
      .studio { padding: 110px 0 30px 0; }
      .sec-head {
        display: flex;
        flex-wrap: wrap;
        align-items: flex-end;
        justify-content: space-between;
        gap: 20px 24px;
        margin-bottom: 40px;
      }
      .sec-head .display { margin-top: 18px; }
      .hint a { color: var(--text); text-decoration: underline; text-underline-offset: 3px; }

      .studio, .archive { overflow: hidden; }
      .studio .wrap, .archive .wrap { z-index: 2; }
      .art-studio {
        right: -2%;
        top: 0;
        height: 560px;
        opacity: 0.85;
        -webkit-mask-image: linear-gradient(to bottom, #000 55%, transparent 100%);
        mask-image: linear-gradient(to bottom, #000 55%, transparent 100%);
      }

      /* ---- Archive (filter grid) ---- */
      .archive { padding: 90px 0 130px 0; }
      .art-archive {
        right: -3%;
        top: 0;
        height: 520px;
        opacity: 0.9;
        -webkit-mask-image: linear-gradient(to bottom, #000 50%, transparent 100%);
        mask-image: linear-gradient(to bottom, #000 50%, transparent 100%);
      }
      .archive .sec-head { margin-bottom: 36px; }

      /* ---- Scroll animation (only when JS is running) ----
         1. Staggered reveal: children of .rv-kids rise out of a blur one
            after another (--i is set per child by the script).
         2. Parallax: every .art[data-speed] drifts, zooms and turns as its
            section crosses the screen (script sets --py / --ps / --pr).
         3. Pinned story: .process.is-pinned sticks to the screen for 340vh
            while the three steps and the flower art swap with scroll.
         Movement uses the individual translate / scale / rotate properties
         so it never fights the transforms the art and tiles already use. */
      :root { --ease-out: cubic-bezier(0.16, 1, 0.3, 1); }

      .js .reveal {
        opacity: 0;
        transform: translateY(70px) scale(0.96);
        filter: blur(8px);
        transition: opacity 1s ease, transform 1.2s var(--ease-out), filter 1s ease;
      }
      .js .reveal.in { opacity: 1; transform: none; filter: none; }
      .step:nth-child(2) { transition-delay: 0.12s; }
      .step:nth-child(3) { transition-delay: 0.24s; }

      .js .rv-kids > * {
        opacity: 0;
        transform: translateY(64px) scale(0.97);
        filter: blur(10px);
        transition: opacity 1s ease, transform 1.2s var(--ease-out), filter 1s ease;
        transition-delay: calc(var(--i, 0) * 130ms);
      }
      .js .rv-kids.in > * { opacity: 1; transform: none; filter: none; }
      .js .hero .rv-kids > * { transition-delay: calc(var(--i, 0) * 130ms + 150ms); }

      /* flowers: parallax drift + slow push-in + slight turn */
      .art { will-change: translate, scale, rotate; }
      .pin-art { scale: 1.14; }
      .pin-art.on { scale: 1; }

      /* (hero copy lift-off, flower drift and pin progress are written by the script every frame) */
      html.lenis, html.lenis body { height: auto; }
      /* Lenis does the easing; native smooth-scroll on top of it would make the page feel laggy */
      html.lenis, html.lenis body { scroll-behavior: auto !important; }
      .lenis.lenis-smooth [data-lenis-prevent] { overscroll-behavior: contain; }
      .lenis.lenis-stopped { overflow: hidden; }

      /* filter tiles pop in one after another the first time the archive shows */
      @keyframes tile-in {
        from { opacity: 0; translate: 0 70px; scale: 0.92; filter: blur(8px); }
        to   { opacity: 1; translate: 0 0;    scale: 1;    filter: blur(0); }
      }
      .js .filter-thumb.rv-tile:not(.in) { opacity: 0; }
      .js .filter-thumb.rv-tile.in {
        animation: tile-in 1s var(--ease-out) calc(var(--i, 0) * 90ms) backwards;
      }
      .js .filter-thumb.rv-tile.in.no-anim { animation: none; }

      /* pinned storytelling (desktop with motion allowed; script adds .is-pinned) */
      .process.is-pinned { height: 340vh; overflow: visible; }
      .process.is-pinned .pin {
        position: sticky;
        top: 0;
        height: 100vh;
        padding: 0;
        display: flex;
        align-items: center;
        overflow: hidden;
      }
      .process.is-pinned .pin .process-grid { width: 100%; }
      .js .process.is-pinned .step {
        opacity: 0.18;
        transform: translateX(34px) scale(0.93);
        filter: none;
        transition: opacity 0.9s ease, transform 1.1s var(--ease-out);
        transition-delay: 0s;
        will-change: opacity, transform;
      }
      .js .process.is-pinned .step.is-past { opacity: 0.45; transform: translateX(0) scale(0.97); }
      .js .process.is-pinned .step.is-active { opacity: 1; transform: translateX(-14px) scale(1.06); }
      .process.is-pinned .step.is-active .step-n {
        background: var(--pill);
        border-color: var(--pill);
        color: var(--pill-ink);
      }
      .step-n { transition: background 0.5s ease, color 0.5s ease, border-color 0.5s ease; }

      /* ---- Control panel ---- */
      .well {
        background: var(--surface);
        border: 1px solid var(--line);
        border-radius: var(--r-card);
        box-shadow: none;
        padding: 26px;
      }
      .well .form-group { margin-bottom: 26px; }

      .control-label, .section-label {
        display: block;
        margin: 0 0 14px 0;
        padding: 0;
        border: 0;
        font-family: var(--sans);
        font-size: 1.05em;
        font-weight: 600;
        letter-spacing: -0.01em;
        color: var(--text);
      }
      hr { border: 0; border-top: 1px solid var(--line); margin: 0; }

      .hint { font-size: 0.95em; color: var(--muted); margin-bottom: 26px; }

      /* ---- File input ---- */
      .input-group { display: flex; width: 100%; }
      .input-group .form-control {
        height: 44px;
        border: 1px solid var(--line-strong);
        border-left: 0;
        border-radius: 0 999px 999px 0 !important;
        box-shadow: none;
        background: var(--sunken) !important;
        color: var(--muted);
        font-size: 0.95em;
        padding-left: 14px;
      }
      /* Bootstrap 3 sets .input-group-btn to font-size: 0, so this must be
         px (an em value would collapse to 0 and hide the Browse label). */
      .input-group-btn { width: auto; }
      .input-group-btn > .btn,
      .btn-file {
        height: 44px;
        padding: 0 20px;
        border: 0 !important;
        border-radius: 999px 0 0 999px !important;
        background: var(--pill);
        color: var(--pill-ink);
        font-weight: 600;
        font-size: 14px;
        line-height: 44px;
        box-shadow: none;
      }
      .input-group-btn > .btn:hover,
      .btn-file:hover {
        background: var(--pill-hover);
        color: var(--pill-ink);
      }
      .progress {
        height: 6px;
        margin: 12px 0 0 0;
        border: 0;
        border-radius: 999px;
        box-shadow: none;
        background: var(--track);
        overflow: hidden;
      }
      .progress-bar {
        background: var(--pill);
        box-shadow: none;
        font-size: 0;
        color: transparent;
      }

      /* ---- Density slider ---- */
      .irs--shiny .irs-line {
        top: 31px;
        height: 6px;
        background: var(--track);
        border: 0;
        border-radius: 999px;
      }
      .irs--shiny .irs-bar {
        top: 31px;
        height: 6px;
        background: var(--pill);
        border: 0;
        border-radius: 999px;
      }
      .irs--shiny .irs-handle,
      .irs--shiny .irs-handle.state_hover,
      .irs--shiny .irs-handle:hover {
        top: 26px;
        width: 26px;
        height: 14px;
        background: var(--pill) !important;
        border: 0 !important;
        border-radius: 999px !important;
        box-shadow: none !important;           /* no glow at rest */
        transition: box-shadow 0.2s ease;
      }
      /* the glow, and the value bubble below, belong to "being used" (see .rl-live in app.js) */
      .irs--shiny.rl-live .irs-handle {
        box-shadow: 0 0 0 5px var(--fill-3), 0 0 18px 4px color-mix(in srgb, var(--pill) 40%, transparent) !important;
      }
      .irs--shiny .irs-handle > i { display: none; }
      .irs--shiny .irs-single {
        background: var(--pill) !important;
        color: var(--pill-ink) !important;
        border: 0;
        border-radius: 999px;
        font-family: var(--sans);
        font-size: 12px;
        font-weight: 600;
        text-shadow: none;
        padding: 2px 9px;
        opacity: 0;
        transform: translateY(5px) scale(0.88);
        transform-origin: 50% 100%;
        transition: opacity 0.16s ease, transform 0.16s ease;
        pointer-events: none;
      }
      .irs--shiny.rl-live .irs-single { opacity: 1; transform: none; }
      .irs--shiny .irs-single:before { display: none; }
      /* at rest the -100% / 100% end labels always show (the library hides one while the bubble overlaps it) */
      .irs--shiny:not(.rl-live) .irs-min,
      .irs--shiny:not(.rl-live) .irs-max { visibility: visible !important; }
      .irs--shiny .irs-min,
      .irs--shiny .irs-max {
        background: transparent !important;
        color: var(--muted) !important;
        font-family: var(--sans);
        font-size: 12px;
        text-shadow: none;
      }
      .irs--shiny .irs-grid-pol { background: var(--line-strong); }
      .irs--shiny .irs-grid-text {
        color: var(--muted);
        font-family: var(--sans);
        font-size: 11px;
      }

      /* ---- Density heading + typed value ---- */
      .density-head {
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 12px;
        margin-bottom: 14px;
      }
      .density-head .section-label { margin: 0; }
      .density-input {
        display: flex;
        align-items: center;
        gap: 8px;
        font-weight: 500;
        color: var(--muted);
      }
      .density-num {
        width: 88px;
        height: 38px;
        padding: 4px 14px;
        border: 1px solid var(--line-strong);
        border-radius: 999px;
        background: var(--sunken);
        color: var(--text);
        box-shadow: none;
        font-size: 1em;
        font-weight: 600;
        text-align: right;
      }
      .density-num:invalid { border-color: var(--rose); color: var(--rose); }

      /* ---- Density legend ---- */
      .density-legend {
        margin-top: 14px;
        padding: 10px 14px;
        border: 1px solid var(--line);
        border-radius: var(--r-inner);
        background: var(--sunken);
        font-size: 0.9em;
        color: var(--muted);
        line-height: 2.1;
      }
      .legend-pct {
        display: inline-block;
        min-width: 58px;
        padding: 0 10px;
        border-radius: 999px;
        font-weight: 600;
        text-align: center;
        margin-right: 8px;
      }
      .legend-neg  { background: var(--track-2); color: var(--text); }
      .legend-zero { background: transparent; color: var(--text); box-shadow: inset 0 0 0 1px var(--line-strong); }
      .legend-pos  { background: var(--pill); color: var(--pill-ink); }
      .legend-over { background: var(--rose); color: var(--pill-ink); }

      /* ---- Filter archive: bento grid of tiles ---- */
      .bento {
        display: grid;
        grid-template-columns: repeat(6, 1fr);
        grid-auto-rows: 230px;
        gap: 16px;
      }
      .filter-thumb {
        position: relative;
        isolation: isolate;
        grid-column: span 2;
        overflow: hidden;
        border: 1px solid var(--line);
        border-radius: var(--r-card);
        background:
          radial-gradient(420px 220px at 85% 0%, var(--glow), transparent 70%),
          linear-gradient(150deg, var(--tile-a), var(--tile-b));
        cursor: pointer;
        transition: transform 0.25s ease, border-color 0.2s ease;
      }
      /* 7-tile rhythm over 3 rows: 4+2 / 2+2+2 / 2+4 */
      .filter-thumb:nth-child(7n+1),
      .filter-thumb:nth-child(7n) { grid-column: span 4; }
      .filter-thumb:hover { transform: translateY(-3px); border-color: var(--line-strong); }
      .filter-thumb img {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        object-fit: cover;
        transition: transform 0.7s cubic-bezier(0.2, 0.7, 0.2, 1);
      }
      .filter-thumb:hover img { transform: scale(1.05); }
      .tile-shade {
        position: absolute;
        inset: 0;
        z-index: 1;
        background: linear-gradient(to top, rgba(10, 10, 10, 0.80), rgba(10, 10, 10, 0) 58%);
      }
      .tile-sample {
        position: absolute;
        top: 14px; left: 14px;
        z-index: 2;
        padding: 3px 10px;
        border: 1px solid rgba(255, 255, 255, 0.2);
        border-radius: 999px;
        background: rgba(10, 10, 10, 0.6);
        -webkit-backdrop-filter: blur(8px);
        backdrop-filter: blur(8px);
        font-size: 10px;
        font-weight: 600;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: rgba(255, 255, 255, 0.8);
      }
      .tile-error {
        position: absolute;
        inset: 0;
        display: grid;
        place-items: center;
        color: var(--rose);
        font-size: 13px;
        font-weight: 600;
      }
      .tile-meta {
        position: absolute;
        left: 22px; right: 22px; bottom: 18px;
        z-index: 2;
        display: flex;
        align-items: baseline;
        justify-content: space-between;
        gap: 12px;
      }
      .thumb-label {
        font-size: 22px;
        font-weight: 600;
        letter-spacing: -0.03em;
        color: #fff;
      }
      .tile-idx {
        font-size: 11px;
        font-weight: 600;
        letter-spacing: 0.14em;
        color: rgba(255, 255, 255, 0.6);
        transition: background 0.15s ease, color 0.15s ease;
      }
      /* selected = hairline turns white, number becomes a pill */
      .filter-thumb.thumb-selected {
        border-color: var(--pill);
        box-shadow: inset 0 0 0 1px var(--pill);
      }
      .filter-thumb.thumb-selected .tile-idx {
        padding: 3px 10px;
        border-radius: 999px;
        background: var(--pill);
        color: var(--pill-ink);
      }

      /* ---- Preview ---- */
      #preview-box {
        position: relative;
        overflow: hidden;
        background: var(--surface);
        border: 1px solid var(--line);
        border-radius: var(--r-card);
        padding: 22px;
        text-align: center;
      }
      #preview-box:fullscreen {
        overflow: auto;
        display: flex;
        flex-direction: column;
        justify-content: center;
        padding: 24px;
        border-radius: 0;
      }
      #preview-box:fullscreen .cmp img { max-height: 76vh; }

      .empty-state {
        min-height: 320px;
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 20px;
        border: 1px dashed var(--line-strong);
        border-radius: var(--r-inner);
        font-size: 1.1em;
        font-weight: 500;
        color: var(--muted);
      }

      /* Shimmer bar that runs while the server is rendering */
      #busy-bar {
        display: none;
        position: absolute;
        top: 0; left: 0; right: 0;
        height: 3px;
        z-index: 5;
        background: repeating-linear-gradient(45deg, var(--pill) 0 10px, var(--track-2) 10px 20px);
        background-size: 28px 28px;
        animation: busy-slide 0.6s linear infinite;
      }
      html.shiny-busy #busy-bar { display: block; }
      @keyframes busy-slide { to { background-position: 28px 0; } }

      /* ---- Status strip ---- */
      .status {
        display: flex;
        justify-content: space-between;
        align-items: center;
        flex-wrap: wrap;
        gap: 4px 16px;
        margin: 0 0 16px 0;
        padding: 10px 18px;
        border: 1px solid var(--line);
        border-radius: 999px;
        background: var(--sunken);
        text-align: left;
        font-weight: 600;
        font-size: 1em;
        color: var(--text);
      }
      .mode-hint {
        display: none;
        font-size: 0.85em;
        font-weight: 400;
        color: var(--muted);
      }
      .mode-filtered .h-filtered,
      .mode-split .h-split,
      .mode-original .h-original { display: inline; }

      /* ---- Toolbar ---- */
      .toolbar {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        justify-content: space-between;
        gap: 14px 16px;
        margin-bottom: 20px;
        text-align: left;
      }
      .seg-group {
        display: inline-flex;
        padding: 4px;
        border: 1px solid var(--line);
        border-radius: 999px;
        background: var(--sunken);
      }
      .seg {
        margin: 0;
        padding: 8px 18px;
        border: 0;
        border-radius: 999px;
        background: transparent;
        color: var(--muted);
        font-weight: 600;
        font-size: 0.95em;
        cursor: pointer;
        transition: background 0.15s ease, color 0.15s ease;
      }
      .seg:hover { color: var(--text); }
      .seg[aria-pressed='true'] { background: var(--pill); color: var(--pill-ink); }

      .tool-row { display: flex; flex-wrap: wrap; flex: 1 1 100%; gap: 8px; }
      button.btn.tool-btn {
        margin: 0;
        padding: 9px 15px;
        background: transparent;
        color: var(--text);
        border: 1px solid var(--line-strong);
        border-radius: 999px;
        box-shadow: none;
        font-weight: 500;
        font-size: 14px;
        line-height: 1.1;
        transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
      }
      button.btn.tool-btn:hover,
      button.btn.tool-btn:focus {
        background: var(--fill-2);
        color: var(--text);
        border-color: var(--line-hi);
      }
      button.btn.tool-btn:active,
      button.btn.tool-btn:active:hover {
        background: var(--fill-3);
        color: var(--text);
        box-shadow: none;
        transform: scale(0.97);
      }
      button.btn.tool-btn:focus:not(:focus-visible) { outline: none; }
      button.btn.tool-btn.tool-primary {
        background: var(--pill);
        color: var(--pill-ink);
        border-color: var(--pill);
        font-weight: 600;
      }
      button.btn.tool-btn.tool-primary:hover,
      button.btn.tool-btn.tool-primary:focus,
      button.btn.tool-btn.tool-primary:active,
      button.btn.tool-btn.tool-primary:active:hover {
        background: var(--pill-hover);
        color: var(--pill-ink);
        border-color: var(--pill-hover);
      }

      /* ---- Before / after stage ---- */
      .cmp {
        position: relative;
        display: inline-block;
        max-width: 100%;
        line-height: 0;
        overflow: hidden;
        border: 1px solid var(--line);
        border-radius: var(--r-inner);
        background: var(--sunken);
        user-select: none;
        -webkit-user-select: none;
        -webkit-touch-callout: none;
      }
      .cmp img {
        display: block;
        max-width: 100%;
        max-height: 480px;
        width: auto;
        height: auto;
        -webkit-user-drag: none;
      }
      #orig_img, #filt_img { display: block; }
      #filt_img {
        position: absolute;
        top: 0; left: 0;
        width: 100%; height: 100%;
      }
      #filt_img img { width: 100%; height: 100%; max-width: none; max-height: none; }
      #filt_img.recalculating { opacity: 1 !important; }

      .mode-filtered .cmp { cursor: pointer; }
      .mode-split .cmp { cursor: ew-resize; touch-action: pan-y; }
      .mode-original #filt_img,
      .peek #filt_img { visibility: hidden; }
      .mode-split #filt_img { clip-path: inset(0 0 0 var(--split, 50%)); }

      .cmp-handle {
        display: none;
        position: absolute;
        top: 0; bottom: 0;
        left: var(--split, 50%);
        width: 0;
        z-index: 3;
      }
      .mode-split .cmp-handle { display: block; }
      .cmp-handle::before {
        content: '';
        position: absolute;
        top: 0; bottom: 0;
        left: -1px;
        width: 2px;
        background: var(--pill);
        box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.45);
      }
      .cmp-handle::after {
        content: '\2194';
        position: absolute;
        top: 50%; left: -20px;
        width: 40px; height: 40px;
        margin-top: -20px;
        line-height: 40px;
        text-align: center;
        font-size: 18px;
        font-weight: 700;
        color: var(--pill-ink);
        background: var(--pill);
        border-radius: 50%;
        box-shadow: 0 6px 20px rgba(0, 0, 0, 0.5);
      }
      .cmp-handle:focus-visible { outline: none !important; }
      .cmp-handle:focus-visible::after {
        box-shadow: 0 0 0 3px var(--bg), 0 0 0 5px var(--pill);
      }

      .tag {
        display: none;
        position: absolute;
        z-index: 2;
        padding: 3px 10px;
        border: 1px solid rgba(255, 255, 255, 0.2);
        border-radius: 999px;
        background: rgba(10, 10, 10, 0.72);
        -webkit-backdrop-filter: blur(8px);
        backdrop-filter: blur(8px);
        color: #f4f4f4;   /* the glass behind it is always dark, in every theme */
        font-size: 11px;
        font-weight: 600;
        line-height: 1.4;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        pointer-events: none;
      }
      .tag-before   { bottom: 12px; left: 12px; }
      .tag-after    { bottom: 12px; right: 12px; }
      .tag-original { top: 12px; left: 12px; background: var(--pill); color: var(--pill-ink); border-color: var(--pill); }
      .mode-split .tag-before,
      .mode-split .tag-after { display: block; }
      .mode-original .tag-original,
      .peek .tag-original { display: block; }

      /* ---- Empty state doubles as a drop zone ---- */
      #dropzone { cursor: pointer; }
      #dropzone:hover {
        background: var(--fill);
        border-color: var(--line-hi);
        color: var(--text);
      }

      #drop-overlay {
        display: none;
        position: fixed;
        inset: 14px;
        z-index: 1000;
        align-items: center;
        justify-content: center;
        padding: 24px;
        background: var(--overlay);
        border: 2px dashed rgba(255, 255, 255, 0.5);
        border-radius: var(--r-card);
        text-align: center;
        font-family: var(--serif);
        font-style: italic;
        font-weight: 400;
        font-size: clamp(2rem, 6vw, 4.5rem);
        line-height: 1.05;
        color: var(--text);
        pointer-events: none;
      }
      #drop-overlay.show { display: flex; }

      /* ---- Toast ---- */
      #toast {
        position: fixed;
        left: 50%;
        bottom: 28px;
        z-index: 1100;
        max-width: 90vw;
        padding: 12px 22px;
        background: var(--pill);
        color: var(--pill-ink);
        border-radius: 999px;
        box-shadow: 0 10px 40px rgba(0, 0, 0, 0.55);
        font-weight: 600;
        opacity: 0;
        transform: translate(-50%, 16px);
        pointer-events: none;
        transition: opacity 0.15s, transform 0.15s;
      }
      #toast.show { opacity: 1; transform: translate(-50%, 0); }

      /* ---- Keyboard shortcut rows (shown in the menu) ---- */
      .keys-row {
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 12px;
        padding: 5px 0;
        color: var(--muted);
      }
      .keys-cap { display: inline-flex; gap: 4px; flex: 0 0 auto; }
      .keys-row > span:last-child { text-align: right; }
      kbd {
        min-width: 26px;
        padding: 1px 8px;
        border: 1px solid var(--line-strong);
        border-radius: 8px;
        background: var(--kbd);
        color: var(--text);
        box-shadow: 0 1px 0 var(--kbd-edge);
        font-family: var(--sans);
        font-size: 0.85em;
        font-weight: 600;
        text-align: center;
      }

      /* ---- Statement ---- */
      .statement { padding: 180px 0; overflow: hidden; text-align: center; }
      .art-bg {
        left: 50%;
        top: 0;
        height: 100%;
        transform: translateX(-50%);
        opacity: 0.26;
        -webkit-mask-image: linear-gradient(to bottom, transparent 0%, #000 22%, #000 78%, transparent 100%);
        mask-image: linear-gradient(to bottom, transparent 0%, #000 22%, #000 78%, transparent 100%);
      }
      .statement .wrap { z-index: 2; }
      .stmt-icon { display: block; width: 56px; height: 56px; margin: 0 auto 22px auto; color: var(--soft); }
      .stmt-icon svg { width: 100%; height: 100%; }
      .statement .display { font-size: clamp(2.6rem, 6.4vw, 4.8rem); }
      .statement p { max-width: 52ch; margin: 22px auto 34px auto; font-size: 16px; line-height: 1.6; color: var(--soft); }

      /* ---- Footer ---- */
      .foot {
        position: relative;
        overflow: hidden;
        padding: 110px 0 36px 0;
        border-top: 1px solid var(--line);
      }
      .ghost {
        position: absolute;
        left: 50%; top: 24px;
        transform: translateX(-50%);
        font-size: 24vw;
        font-weight: 800;
        line-height: 0.8;
        letter-spacing: -0.06em;
        white-space: nowrap;
        color: var(--ghost);
        pointer-events: none;
        user-select: none;
      }
      .art-foot {
        right: -6%;
        top: 0;
        height: 118%;
        opacity: 0.30;
        -webkit-mask-image: linear-gradient(to bottom, transparent 0%, #000 30%);
        mask-image: linear-gradient(to bottom, transparent 0%, #000 30%);
      }
      .foot .wrap { z-index: 2; }
      .foot-top { display: grid; grid-template-columns: 1.5fr 1fr 1fr 1fr; gap: 48px; }
      .foot-brand .display { font-size: clamp(2.6rem, 5vw, 4rem); }
      .tag-serif { margin: 8px 0 18px 0; font-family: var(--serif); font-style: italic; font-size: 18px; color: var(--rose); }
      .foot-brand .sub { max-width: 34ch; margin-top: 0; }
      .foot-col h4 {
        display: flex;
        align-items: center;
        gap: 8px;
        margin: 4px 0 16px 0;
        font-size: 11px;
        font-weight: 600;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        color: var(--text);
      }
      .foot-col h4::before { content: ''; width: 5px; height: 5px; border-radius: 50%; background: var(--rose); }
      .foot-col a, .foot-col span {
        display: block;
        padding: 4px 0;
        font-size: 14px;
        color: var(--muted);
        text-decoration: none !important;
      }
      .foot-col a:hover { color: var(--text); }
      .foot-bar {
        display: grid;
        grid-template-columns: 1fr auto 1fr;
        align-items: center;
        gap: 10px 24px;
        margin-top: 90px;
        padding-top: 24px;
        border-top: 1px solid var(--line);
        font-size: 11px;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--muted);
      }

      /* ---- Mini preview that follows you down the page ---- */
      #dock {
        position: fixed;
        right: 24px; bottom: 24px;
        z-index: 900;
        width: 176px;
        padding: 6px;
        border: 1px solid var(--line-strong);
        border-radius: 20px;
        background: var(--glass-strong);
        -webkit-backdrop-filter: blur(12px);
        backdrop-filter: blur(12px);
        box-shadow: 0 16px 50px rgba(0, 0, 0, 0.6);
        text-align: left;
        cursor: pointer;
        opacity: 0;
        transform: translateY(14px);
        pointer-events: none;
        transition: opacity 0.2s ease, transform 0.2s ease;
      }
      #dock.show { opacity: 1; transform: none; pointer-events: auto; }
      #dock img { display: block; width: 100%; height: 112px; object-fit: cover; border-radius: 14px; }
      #dock span {
        display: block;
        padding: 8px 8px 2px 8px;
        overflow: hidden;
        white-space: nowrap;
        text-overflow: ellipsis;
        font-size: 12px;
        font-weight: 600;
        color: var(--text);
      }
      #dock small { display: block; padding: 0 8px 4px 8px; font-size: 11px; color: var(--muted); }

      @media (max-width: 991px) {
        .process-grid { grid-template-columns: 1fr; gap: 56px; }
        .bento { grid-template-columns: repeat(4, 1fr); grid-auto-rows: 200px; }
        .filter-thumb,
        .filter-thumb:nth-child(7n+1),
        .filter-thumb:nth-child(7n) { grid-column: span 2; }
        .filter-thumb:last-child { grid-column: span 4; }
        .foot-top { grid-template-columns: 1fr 1fr; }
        .foot-brand { grid-column: 1 / -1; }
      }
      @media (max-width: 767px) {
        .wrap { padding: 0 20px; }
        .nav-in { height: 64px; padding: 0 20px; grid-template-columns: auto auto; justify-content: space-between; }
        .nav-links { display: none; }
        .nav-right .pill { display: none; }
        .hero { padding: 120px 0 90px 0; }
        .art-hero { right: -34%; top: 6%; height: 82%; opacity: 0.55; }
        .pin { padding: 100px 0; }
        .pin-art.on { opacity: 0.4; }
        .art-studio, .art-archive { height: 380px; opacity: 0.35; }
        .step:nth-child(even) { margin-left: 0; }
        .studio { padding-top: 80px; }
        .archive { padding: 60px 0 90px 0; }
        .bento { grid-template-columns: repeat(2, 1fr); grid-auto-rows: 170px; gap: 12px; }
        .filter-thumb,
        .filter-thumb:nth-child(7n+1),
        .filter-thumb:nth-child(7n) { grid-column: span 1; }
        .filter-thumb:last-child { grid-column: span 2; }
        .tile-meta { left: 16px; right: 16px; bottom: 14px; }
        .thumb-label { font-size: 17px; }
        .statement { padding: 110px 0; }
        .foot { padding-top: 80px; }
        .foot-top { grid-template-columns: 1fr; gap: 32px; }
        .foot-bar { margin-top: 56px; grid-template-columns: 1fr; justify-items: center; text-align: center; }
        .foot-bar > span:last-child { text-align: center; }
        .well { margin-bottom: 28px; padding: 20px; }
        #preview-box { padding: 14px; }
        /* phones: just a small thumbnail, so it never hides the controls underneath */
        #dock { width: 84px; right: 12px; bottom: 12px; padding: 4px; border-radius: 16px; }
        #dock img { height: 60px; border-radius: 12px; }
        #dock span, #dock small { display: none; }
      }
      @media (prefers-reduced-motion: reduce) {
        html { scroll-behavior: auto; }
        * { transition: none !important; }
        #busy-bar { animation: none; }
        /* reduced motion: reveals become a plain fade, no drift / blur / parallax */
        .js .reveal, .js .rv-kids > * { transform: none; filter: none; transition: opacity 0.6s ease !important; }
        .art { translate: none; scale: none; rotate: none; }
        .js .filter-thumb.rv-tile { opacity: 1; animation: none; }
      }

/* ---- additions ---- */
.filter-thumb.is-loading img { opacity: 0.25; filter: blur(6px); transition: opacity .3s, filter .3s; }
.filter-thumb img { transition: opacity .3s, filter .3s, transform .5s; }
.keys-toggle { display: flex; gap: 8px; align-items: center; margin-top: 12px; font-size: 12px; color: var(--muted); cursor: pointer; }
.keys-toggle input { accent-color: var(--pill); }


/* ---- Download split button:  [icon] Download | .png v ---- */
.dl-split {
  display: inline-flex; align-items: center; overflow: hidden;
  padding: 0;                             /* the format pill is flush with the top, bottom and right edges */
  background: var(--pill); border-radius: 999px;
  transition: background .15s ease, transform .15s ease;
}
.dl-split:hover { background: var(--pill-hover); transform: translateY(-1px); }
.dl-split:active { background: var(--pill-active); }
.dl-split a.btn.btn-download-top.dl-main,
.dl-split a.btn.btn-download-top.dl-main:hover,
.dl-split a.btn.btn-download-top.dl-main:focus,
.dl-split a.btn.btn-download-top.dl-main:active {
  background: transparent; transform: none; border-radius: 0; height: 45px; padding: 0 18px 0 28px;
}
/* ---- Layers, looks, undo/redo ---- */
button.btn.tool-btn:disabled { opacity: .38; cursor: not-allowed; transform: none; background: transparent; }
/* Share link + Save look: where the shortcuts card used to be (sidebar, under the legend) */
.look-actions { text-align: left; }
.look-btns { display: flex; gap: 8px; margin-top: 22px; }
.look-btns button.btn.tool-btn { flex: 1 1 0; justify-content: center; text-align: center; white-space: nowrap; }
.my-looks:not(:empty) { margin-top: 12px; }
.my-looks:empty { display: none; }
#layer_chips { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.layer-chip, .look-chip {
  display: inline-flex; align-items: center; gap: 8px; padding: 5px 6px 5px 13px;
  border: 1px solid var(--line-strong); border-radius: 999px;
  font-size: 13px; color: var(--text); background: var(--sunken);
}
.layer-chip button, .look-chip button.look-x {
  width: 20px; height: 20px; padding: 0; line-height: 1; border: 0; border-radius: 50%;
  background: var(--fill-2); color: var(--text); cursor: pointer; font-size: 14px;
}
.layer-chip button:hover, .look-chip button.look-x:hover { background: var(--fill-3); }
.look-chip button.look-use { border: 0; background: transparent; color: inherit; font: inherit; padding: 0; cursor: pointer; }
.my-looks { display: inline-flex; flex-wrap: wrap; gap: 8px; }
.filt-instant #filt_img img { transition: none; }

/* ---- Download format menu (replaces the browser's native <select> list) ---- */
.dl-wrap { position: relative; display: inline-block; z-index: 30; }
.dl-split button.dl-fmt {
  display: inline-flex; align-items: center; gap: 8px; cursor: pointer;
  height: 45px; margin: 0; padding: 0 18px 0 22px;
  background: transparent; color: var(--pill-ink);          /* outlined pill: same fill as the Download pill */
  border: 0; border-radius: 999px;
  box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--pill-ink) 55%, transparent);
  font: 600 14px/1 var(--sans, inherit);
  transition: background .15s ease, box-shadow .15s ease;
}
.dl-split button.dl-fmt:hover,
.dl-split button.dl-fmt[aria-expanded="true"] {
  background: color-mix(in srgb, var(--pill-ink) 7%, transparent);
  box-shadow: inset 0 0 0 1.5px var(--pill-ink);
}
.dl-split button.dl-fmt svg { opacity: .6; transition: transform .18s ease; }
.dl-split button.dl-fmt[aria-expanded="true"] svg { transform: rotate(180deg); }
.dl-split button.dl-fmt:focus-visible { outline: 2px solid var(--pill-ink); outline-offset: -6px; }
.dl-native { display: none; }   /* the menu sets it; Shiny still reads its value */
.dl-menu {
  position: absolute; left: 0; right: 0; top: calc(100% + 10px); min-width: 210px; padding: 6px;
  background: var(--surface); border: 1px solid var(--line-strong); border-radius: 24px;
  box-shadow: 0 22px 48px rgba(0, 0, 0, .45);
  opacity: 0; visibility: hidden; transform: translateY(-6px) scale(.98); transform-origin: top right;
  transition: opacity .15s ease, transform .15s ease, visibility 0s linear .15s;
}
.dl-menu.open { opacity: 1; visibility: visible; transform: none; transition-delay: 0s; }
.dl-opt {
  display: flex; align-items: center; gap: 12px; width: 100%; margin: 0; padding: 12px 14px 12px 18px;
  border: 0; border-radius: 999px; background: transparent; color: var(--text);
  font: 600 15px/1 var(--sans, inherit); text-align: left; cursor: pointer;
  transition: background .12s ease;
}
.dl-opt + .dl-opt { margin-top: 2px; }
.dl-opt-hint { margin-left: auto; font-weight: 400; font-size: 12px; color: var(--muted); }
.dl-opt-check { display: inline-flex; width: 16px; justify-content: center; opacity: 0; }
.dl-opt:hover, .dl-opt:focus-visible { background: var(--fill-2); outline: none; }
.dl-opt[aria-selected="true"] { background: var(--pill); color: var(--pill-ink); }
.dl-opt[aria-selected="true"]:hover, .dl-opt[aria-selected="true"]:focus-visible { background: var(--pill-hover); }
.dl-opt[aria-selected="true"] .dl-opt-hint { color: color-mix(in srgb, var(--pill-ink) 62%, transparent); }
.dl-opt[aria-selected="true"] .dl-opt-check { opacity: 1; }

/* ---- Remove photo: a cross in the file box, and a cross on the photo itself ---- */
.btn-file { position: relative; overflow: hidden; }   /* the real file input sits on top of "Browse..." */
.file-x {
  display: none; position: absolute; right: 8px; top: 8px;     /* 44px pill - 28px circle = 8px all round */
  width: 28px; height: 28px; padding: 0; border: 0; border-radius: 50%;
  align-items: center; justify-content: center; line-height: 0;
  background: var(--fill-3); color: var(--text); cursor: pointer; z-index: 3;
  opacity: 0; transform: scale(.6); pointer-events: none;
  transition: opacity .16s ease, transform .16s ease, background .12s ease;
}
.has-photo .file-x { display: inline-flex; }
.file-x.near, .file-x:focus-visible { opacity: 1; transform: none; pointer-events: auto; }
.file-x.near:hover { background: var(--line-strong); }
.file-x:focus-visible { outline: 2px solid var(--text); outline-offset: 2px; }
@media (hover: none) { .has-photo .file-x { opacity: 1; transform: none; pointer-events: auto; } }
.has-photo .input-group .form-control { padding-right: 48px; }

.photo-x {
  position: absolute; top: 12px; right: 12px; z-index: 6; width: 30px; height: 30px; padding: 0;
  display: inline-flex; align-items: center; justify-content: center; line-height: 0;
  border: 0; border-radius: 50%; background: #fff; color: #111; cursor: pointer;
  box-shadow: 0 2px 12px rgba(0, 0, 0, .42);
  opacity: 0; transform: scale(.6); pointer-events: none;
  transition: opacity .16s ease, transform .16s ease, background .12s ease;
}
.photo-x.near, .photo-x:focus-visible { opacity: 1; transform: none; pointer-events: auto; }
.photo-x.near:hover { background: #ececec; transform: scale(1.08); }
.photo-x:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
@media (hover: none) { .photo-x { opacity: 1; transform: none; pointer-events: auto; } }

/* ---- "Filters archive" button (sidebar) ---- */
.archive-btn {
  display: flex; align-items: center; justify-content: center; text-align: center;
  margin: 0 0 26px; padding: 13px 20px;
  border: 1px solid var(--line-strong); border-radius: 999px;
  color: var(--pill-ink) !important; font-size: 14px; font-weight: 600; line-height: 1.1;
  text-decoration: none !important; background: var(--pill); border-color: var(--pill);
  transition: background .15s ease, border-color .15s ease, transform .1s ease;
}
.archive-btn:hover, .archive-btn:focus-visible {
  background: var(--pill-hover); border-color: var(--pill-hover); color: var(--pill-ink) !important; outline: none;
}
.archive-btn:active { background: var(--pill-active); border-color: var(--pill-active); transform: scale(.98); }

/* ---- Footer: the GitHub link blends into the bottom line ---- */
.foot-bar > span:first-child { justify-self: start; }
.foot-bar > span:last-child { justify-self: end; text-align: right; }
.foot-bar > .foot-mid { justify-self: center; }
@media (max-width: 760px) { .foot-bar > span:first-child, .foot-bar > span:last-child { justify-self: center; } }
.foot-gh { color: inherit !important; text-decoration: none !important; transition: color .15s ease; }
.foot-gh:hover, .foot-gh:focus-visible { color: var(--text) !important; text-decoration: underline !important; text-underline-offset: 3px; }
)---"



