          (function() {
            var btn = document.getElementById('menu-btn');
            var panel = document.getElementById('menu-panel');
            if (!btn || !panel) return;
            var GUIDE_URL = 'https://github.com/BERSERKER1706/Retro/blob/main/README.md';
            var root = document.documentElement;
            var views = {};
            [].slice.call(panel.querySelectorAll('.menu-view')).forEach(function(v) {
