  /* ---------- 1. Instant browser-side preview ----------
     While the server renders the exact result (about half a second), the browser shows a
     CSS-filter approximation of it on the un-filtered photo, so the slider feels instant.
     The real render replaces it the moment it arrives. Filters without a good CSS
     equivalent (Vignette, Grain, Poster, Emboss, Sketch, Pixelate) just wait for the server. */
  function cl(x) { return Math.max(0, Math.min(1, x)); }
  function fxFor(name, d, longSide) {
    var t = (d <= 0 ? 100 + 2 * d : 100 + d) / 100;           // same maths as density_to_t() in R
    function sm(target) { return Math.max(0, 100 + (target - 100) * t) / 100; }
    switch (name) {
      case 'Sepia':     return 'saturate(' + sm(40) + ') sepia(' + cl(0.55 * t) + ')';
      case 'Faded':     return t > 0 ? 'brightness(' + sm(105) + ') saturate(' + sm(80) + ') contrast(' + Math.max(0.3, 1 - 0.2 * t) + ')'
                                     : 'brightness(' + (1 + 0.08 * t) + ') saturate(' + (1 - 0.25 * t) + ')';
      case 'Noir':      return 'saturate(' + sm(0) + ') contrast(' + (1 + 0.6 * Math.max(0, t - 1)) + ')';
      case 'Duotone':   return 'saturate(' + sm(0) + ') sepia(' + cl(0.5 * t) + ') hue-rotate(175deg) saturate(1.3)';
      case 'Vintage':   return 'brightness(' + sm(95) + ') saturate(' + sm(70) + ') sepia(' + cl(0.2 * t) + ')';
      case 'Warm':      return 'brightness(' + sm(105) + ') saturate(' + sm(120) + ') sepia(' + cl(0.12 * t) + ')';
      case 'Cool':      return 'brightness(' + sm(105) + ') saturate(' + sm(90) + ') sepia(' + cl(0.2 * t) + ') hue-rotate(170deg)';
      case 'Dramatic':  return 'brightness(' + sm(90) + ') saturate(' + sm(115) + ') contrast(' + Math.max(0.3, 1 + 0.22 * t) + ')';
      case 'Bright':    return 'brightness(' + sm(125) + ') saturate(' + sm(110) + ')';
      case 'Moody':     return 'brightness(' + sm(75) + ') saturate(' + sm(90) + ') contrast(' + Math.max(0.3, 1 + 0.2 * t) + ')';
      case 'Cyanotype': return 'saturate(' + sm(0) + ') sepia(' + cl(0.6 * t) + ') hue-rotate(175deg) saturate(1.5)';
      case 'Sunset':    return 'brightness(' + sm(105) + ') saturate(' + sm(135) + ') sepia(' + cl(0.22 * t) + ') hue-rotate(-12deg)';
      case 'Negative':  return 'invert(' + cl(t) + ')';
      case 'Blur':      return t > 0 ? 'blur(' + (0.004 * longSide * t).toFixed(2) + 'px)' : null;
      default:          return null;
    }
  }
  function selectedFilter() { return $('.filter-thumb.thumb-selected').attr('data-filter') || 'Original'; }
  function instant(name, d) {
    if (layersCount > 0 || !name || name === 'Original') return;     // stacked layers need the server
    var img = document.querySelector('#filt_img img'), o = document.querySelector('#orig_img img');
    if (!img || !o || String(o.src).indexOf('data:image/jpeg') !== 0) return;
    var fx = fxFor(name, d, Math.max(img.clientWidth, img.clientHeight));
    if (fx === null) return;
    if (img.getAttribute('src') !== o.getAttribute('src')) img.setAttribute('src', o.getAttribute('src'));
    img.dataset.instant = o.getAttribute('src').length + '';
    img.style.filter = fx;
  }
  // when the real render replaces the image, drop the approximation
  $(function() {
    var img = document.querySelector('#filt_img img');
    if (!img) return;
    new MutationObserver(function() {
      var o = document.querySelector('#orig_img img');
      if (img.dataset.instant && o && img.getAttribute('src') !== o.getAttribute('src')) {
        img.style.filter = ''; delete img.dataset.instant;
      }
    }).observe(img, { attributes: true, attributeFilter: ['src'] });
  });
  $(document).on('input change', '#density', function() { instant(selectedFilter(), parseFloat(this.value) || 0); });
  $(document).on('click', '.filter-thumb:not(.is-empty)', function() { instant(this.getAttribute('data-filter'), 0); });

  /* ---------- 2. Undo / redo keys ---------- */
  document.addEventListener('keydown', function(e) {
    if (!(e.ctrlKey || e.metaKey) || e.altKey || !shortcutsOn()) return;
    var k = (e.key || '').toLowerCase();
    if (k !== 'z' && k !== 'y') return;
    var t = e.target, tag = t && t.tagName;
    if (tag === 'TEXTAREA' || tag === 'SELECT' || (t && t.isContentEditable) ||
        (tag === 'INPUT' && /^(text|number|search|email|url|password)$/.test(t.type))) return;
    if (!$('#cmp').is(':visible')) return;
    e.preventDefault();
    setInput((k === 'y' || e.shiftKey) ? 'redo' : 'undo', Date.now());
  });

  whenShiny(function() {
    /* ---------- 3. State from the server: undo/redo buttons, layer count ---------- */
    Shiny.addCustomMessageHandler('edit_state', function(m) {
      layersCount = m.layers || 0;
      $('#undo').prop('disabled', !m.undo);
      $('#redo').prop('disabled', !m.redo);
    });

    /* ---------- 4. Remove photo: back to the starting screen ---------- */
    Shiny.addCustomMessageHandler('photo_removed', function(_unused) {
      var inp = document.getElementById('image');
      if (inp) {
        inp.value = '';
        $(inp).closest('.input-group').find('input[type=text]').val('');
        $('#image_progress').css('visibility', 'hidden');
      }
      Shiny.setInputValue('image', null);            // so choosing the same file again still fires
      $('.filter-thumb').removeClass('thumb-selected is-loading').addClass('is-empty').each(function() {
        var im = this.querySelector('img'), s = im && im.getAttribute('data-sample');
        if (s) { im.setAttribute('src', s); im.alt = (this.getAttribute('data-filter') || '') + ' sample'; }
      });
      $('.tile-sample').css('display', '');
      var gif = 'data:image/gif;base64,R0lGODlhAQABAAAAACwAAAAAAQABAAA=';
      $('#orig_img img, #filt_img img').attr('src', gif).css('filter', '');
      layersCount = 0;
      toast('Photo removed. Upload a new one to start again');
      document.documentElement.classList.remove('has-photo');
      var st = document.getElementById('studio');
      if (st && window.rlGoTo) rlGoTo(st, false);
    });

    /* ---------- 5. Looks: share link + saved presets (kept in this browser) ---------- */
    Shiny.addCustomMessageHandler('copy_look', function(code) {
      var url = location.origin + location.pathname + '#look=' + code;
      function done() { toast('Share link copied'); }
      function fallback() { window.prompt('Copy this link:', url); }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(url).then(done, fallback);
      else fallback();
    });
    Shiny.addCustomMessageHandler('store_look', function(m) {
      var list = readLooks().filter(function(l) { return l.name !== m.name; });
      list.unshift({ name: m.name, code: m.code });
      writeLooks(list.slice(0, 12));
      renderLooks();
      toast('Saved "' + m.name + '"');
    });

    function applyFromHash() {
      var m = /[#&]look=([A-Za-z0-9_.\-]+)/.exec(location.hash || '');
      if (!m) return;
      setInput('apply_look', m[1]);
      try { history.replaceState(null, '', location.pathname + location.search); } catch (e) {}
    }
    if (Shiny.shinyapp && Shiny.shinyapp.isConnected && Shiny.shinyapp.isConnected()) applyFromHash();
    else $(document).one('shiny:connected', applyFromHash);
  });

  function readLooks() {
    try { var l = JSON.parse(localStorage.getItem('rl-looks') || '[]'); return Array.isArray(l) ? l : []; }
    catch (e) { return []; }
  }
  function writeLooks(list) { try { localStorage.setItem('rl-looks', JSON.stringify(list)); } catch (e) {} }
  function renderLooks() {
    var host = document.getElementById('my-looks');
    if (!host) return;
    host.textContent = '';
    readLooks().forEach(function(l) {
      var chip = document.createElement('span'); chip.className = 'look-chip';
      var use = document.createElement('button'); use.type = 'button'; use.className = 'look-use';
      use.textContent = String(l.name); use.title = 'Apply this look';
      use.addEventListener('click', function() { setInput('apply_look', l.code); });
      var x = document.createElement('button'); x.type = 'button'; x.className = 'look-x';
      x.innerHTML = '&times;'; x.setAttribute('aria-label', 'Delete look ' + l.name); x.title = 'Delete this look';
      x.addEventListener('click', function() {
        writeLooks(readLooks().filter(function(o) { return o.name !== l.name; }));
        renderLooks();
      });
      chip.appendChild(use); chip.appendChild(x); host.appendChild(chip);
    });
  }
  $(function() {
    renderLooks();
    $(document).on('click', '#btn-share', function() { setInput('share_look', Date.now()); });
    $(document).on('click', '#btn-save-look', function() {
      var name = window.prompt('Name this look (saved in this browser):', 'My look ' + (readLooks().length + 1));
      if (name && name.trim()) setInput('save_look', name.trim());
    });
  });
})();

/* ---------- v2.2: upload keeps its place, format menu, remove-photo crosses ---------- */
(function() {
  var NEAR_PX = 19;                      // about 0.5 cm: how close the pointer must get to reveal the cross

  $(function() {
    /* 1. Uploading no longer throws the page back to the top.
       Shiny parks the real <input type=file> 100000px off-screen. When the browser focuses it
       (the Browse click does), it scrolls to the nearest reachable spot, which is the very top
       of a long page. Keep the input where it belongs: invisible, on top of the Browse button. */
    var inp = document.getElementById('image');
    if (inp) {
      [['position', 'absolute'], ['top', '0'], ['left', '0'], ['right', 'auto'], ['width', '100%'],
       ['height', '100%'], ['min-width', '0'], ['opacity', '0'], ['cursor', 'pointer'], ['z-index', '2']
      ].forEach(function(p) { inp.style.setProperty(p[0], p[1], 'important'); });
    }

    /* 2. Remove photo: one function, three triggers (file box cross, photo cross, server event) */
    function removePhoto() {
      if (!document.documentElement.classList.contains('has-photo')) return;
      ['photo-x', 'file-x'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.classList.remove('near');
      });
      Shiny.setInputValue('remove_photo', Date.now(), { priority: 'event' });
    }
    var grp = inp && inp.closest('.input-group');
    if (grp && !document.getElementById('file-x')) {
      var fx = document.createElement('button');
      fx.type = 'button'; fx.id = 'file-x'; fx.className = 'file-x';
      fx.title = 'Remove photo'; fx.setAttribute('aria-label', 'Remove photo');
      fx.innerHTML = "<svg viewBox='0 0 24 24' width='14' height='14' fill='none' stroke='currentColor' " +
                     "stroke-width='2' stroke-linecap='round' stroke-linejoin='round' aria-hidden='true'>" +
                     "<path d='M6 6l12 12M18 6L6 18'/></svg>";
      grp.appendChild(fx);
    }
    $(document).on('click', '#file-x, #photo-x', function(e) { e.preventDefault(); removePhoto(); });

    /* 3. Both crosses (file box, photo) show up only while the pointer is within ~0.5 cm of them */
    var lx = -1e4, ly = -1e4, raf = 0;
    function proximity() {
      raf = 0;
      ['photo-x', 'file-x'].forEach(function(id) {
        var el = document.getElementById(id);
        if (!el || !el.offsetWidth) return;
        var r = el.getBoundingClientRect(), cx = r.left + r.width / 2, cy = r.top + r.height / 2;
        el.classList.toggle('near', Math.hypot(lx - cx, ly - cy) - el.offsetWidth / 2 <= NEAR_PX);
      });
    }
    function schedule() { if (!raf) raf = requestAnimationFrame(proximity); }
    document.addEventListener('pointermove', function(e) {
      if (e.pointerType === 'touch') return;
      lx = e.clientX; ly = e.clientY; schedule();
    }, { passive: true });
    window.addEventListener('scroll', schedule, { passive: true });
    document.documentElement.addEventListener('mouseleave', function() {
      lx = ly = -1e4; schedule();
    });

    /* 3b. Density slider: the value bubble and the glow show only while it is being used
       (pointer over the handle, dragging anywhere, or keyboard focus) */
    (function() {
      var down = false, over = false, kbd = false;
      function paint() {
        var s = document.querySelector('.irs--shiny');
        if (s) s.classList.toggle('rl-live', down || over || kbd);
      }
      document.addEventListener('pointerdown', function(e) {
        if (e.target.closest && e.target.closest('.irs--shiny')) { down = true; paint(); }
      }, true);
      function release() { if (down) { down = false; paint(); } }
      window.addEventListener('pointerup', release, true);
      window.addEventListener('pointercancel', release, true);
      window.addEventListener('blur', release);
      document.addEventListener('pointermove', function(e) {
        if (down && e.buttons === 0) release();          // the button was let go outside the window
      }, { passive: true });
      document.addEventListener('pointerover', function(e) {
        if (e.pointerType === 'mouse' && e.target.closest && e.target.closest('.irs-handle')) { over = true; paint(); }
      });
      document.addEventListener('pointerout', function(e) {
        if (e.pointerType !== 'mouse' || !(e.target.closest && e.target.closest('.irs-handle'))) return;
        var to = e.relatedTarget;
        if (!(to && to.closest && to.closest('.irs-handle'))) { over = false; paint(); }
      });
      document.addEventListener('focusin', function(e) {
        if (e.target.closest && e.target.closest('.irs--shiny')) {
          try { kbd = e.target.matches(':focus-visible'); } catch (err) { kbd = false; }
          paint();
        }
      });
      document.addEventListener('focusout', function(e) {
        if (e.target.closest && e.target.closest('.irs--shiny')) { kbd = false; paint(); }
      });
    })();

    /* 4. Download format menu (the real value lives in the hidden <select id="dl_format">) */
    var wrap = document.querySelector('.dl-wrap'), btn = document.getElementById('dl_fmt_btn'),
        menu = document.getElementById('dl_menu'), sel = document.getElementById('dl_format');
    if (!(wrap && btn && menu && sel)) return;
    var label = btn.querySelector('.dl-fmt-label');
    function items() { return [].slice.call(menu.querySelectorAll('.dl-opt')); }
    function isOpen() { return menu.classList.contains('open'); }
    function setOpen(on, giveFocusBack) {
      menu.classList.toggle('open', on);
      btn.setAttribute('aria-expanded', on ? 'true' : 'false');
      if (on) {
        var cur = menu.querySelector('[aria-selected="true"]') || items()[0];
        if (cur) cur.focus({ preventScroll: true });
      } else if (giveFocusBack) {
        btn.focus({ preventScroll: true });
      }
    }
    function choose(value) {
      var text = '';
      items().forEach(function(o) {
        var on = o.getAttribute('data-value') === value;
        o.setAttribute('aria-selected', on ? 'true' : 'false');
        if (on) text = o.querySelector('.dl-opt-ext').textContent;
      });
      if (!text) return;
      sel.value = value;
      $(sel).trigger('change');                       // Shiny picks the new format up from here
      if (label) label.textContent = text;
      btn.setAttribute('aria-label', 'File format: ' + text);
      setOpen(false, true);
    }
    btn.addEventListener('click', function() { setOpen(!isOpen(), false); });
    menu.addEventListener('click', function(e) {
      var o = e.target.closest('.dl-opt');
      if (o) choose(o.getAttribute('data-value'));
    });
    document.addEventListener('click', function(e) {
      if (isOpen() && !e.target.closest('.dl-wrap')) setOpen(false, false);
    });
    // keys stay inside the menu (the page-wide shortcuts must not also fire)
    wrap.addEventListener('keydown', function(e) {
      var k = e.key;
      if (k === 'Tab') { if (isOpen()) setOpen(false, false); return; }
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      e.stopPropagation();
      var list = items(), i = list.indexOf(document.activeElement);
      if (k === 'Escape') { if (isOpen()) { setOpen(false, true); e.preventDefault(); } }
      else if (k === 'ArrowDown' || k === 'ArrowUp') {
        e.preventDefault();
        if (!isOpen()) { setOpen(true, false); return; }
        var step = k === 'ArrowDown' ? 1 : -1;
        list[(i + step + list.length) % list.length].focus({ preventScroll: true });
      }
      else if (isOpen() && (k === 'Home' || k === 'End')) {
        e.preventDefault(); list[k === 'Home' ? 0 : list.length - 1].focus({ preventScroll: true });
      }
    });
  });
})();
)---"


# ---- R/ui.R ----
# =========================================================
# USER INTERFACE  -  DARK STUDIO
#   Styles are APP_CSS, behaviour is APP_JS (both embedded further up this file).
#   Built inside a function so nothing runs at source time.
# =========================================================

build_ui <- function() {
  fluidPage(
    title = "Retro Lens - analog photo filters",
    lang = "en",

    tags$head(
      tags$meta(name = "viewport", content = "width=device-width, initial-scale=1"),
      tags$meta(name = "description",
                content = "Retro Lens: twenty-one analog photo filters with one density slider. Built with R, Shiny and magick."),
      tags$meta(property = "og:title", content = "Retro Lens"),
      tags$meta(property = "og:description", content = "Twenty-one analog moods, one density slider."),
      tags$meta(property = "og:image", content = "art/sample-02.jpg"),
      tags$link(rel = "icon", href = "art/sample-02.jpg"),
      tags$style(HTML(APP_CSS)),
      # theme flag first, so there is no flash of the wrong theme
      tags$script(HTML(paste0(
        "document.documentElement.classList.add('js');",
        "try { var t = localStorage.getItem('rl-theme'), h = document.documentElement; ",
        "if (t === 'light') h.setAttribute('data-theme', 'light'); ",
        "else if (/^(buttermilk|midnight|seashell|tangerine|lavender|plum|marigold|blush|butternut|cherry|olive|beige)$/.test(t)) ",
        "{ h.setAttribute('data-theme', t); h.setAttribute('data-pal', '1'); } } catch (e) {}",
        # failsafe: if the scroll engine never starts, show everything instead of leaving it hidden
        "setTimeout(function(){ if (!window.__rvReady) document.documentElement.classList.remove('js'); }, 8000);"
      ))),
      # Lenis (inertial scrolling), embedded. The page works without it.
      tags$script(HTML(LENIS_JS)),
      tags$script(HTML(APP_JS))
    ),

    div(id = "drop-overlay", `aria-hidden` = "true", "Drop your photo to load it"),
    div(id = "toast", role = "status", `aria-live` = "polite"),

    # ---------------------------------------------------------------
    # Page sections (Floria-style, one long page):
    #   nav -> hero -> process -> studio (editor) -> archive (filters)
    #   -> statement -> footer, plus a mini-preview dock
    # ---------------------------------------------------------------

    # ---- Navigation ----
    tags$nav(
      id = "nav", class = "nav",
      div(
        class = "nav-in",
        tags$a(class = "logo", href = "#top", logo_svg, "Retro Lens."),
        div(
          class = "nav-links",
          tags$a(href = "#process", "Process"),
          tags$a(href = "#studio", "Studio"),
          tags$a(href = "#archive", "Archive")
        ),
        div(
          class = "nav-right",
          tags$a(class = "pill", href = "#studio", "Open studio"),
          div(
            class = "menu-wrap",
            tags$button(
              id = "menu-btn", class = "menu-btn", type = "button",
              `aria-label` = "Open menu", `aria-haspopup` = "dialog",
              `aria-expanded` = "false", `aria-controls` = "menu-panel",
              tags$i(), tags$i(), tags$i()
            ),
            div(
              id = "menu-panel", class = "menu-panel", role = "dialog", `aria-label` = "Menu",

              # main list
              div(
                class = "menu-view", `data-view` = "main",
                menu_nav("Themes", icon_theme, view = "themes"),
                menu_nav("Colour combo", icon_combo, view = "combos"),
                menu_nav("Shortcut keys", icon_keys, view = "keys"),
                menu_nav("Guide", icon_guide, action = "guide",
                         label_for_readers = "Guide (opens in a new tab)")
              ),

              menu_view(
                "themes", "Themes",
                div(role = "radiogroup", `aria-label` = "Theme",
                    theme_row("dark", "Dark", "swatch-dark", checked = TRUE),
                    theme_row("light", "Light", "swatch-light"))
              ),

              menu_view(
                "combos", "Colour combo",
                div(
                  role = "radiogroup", `aria-label` = "Colour combo",
                  combo_row(c("buttermilk", "Buttermilk",    "#FFF2BA", "#0F3C65"),
                            c("midnight",   "Midnight Blue", "#0F3C65", "#FFF2BA")),
                  combo_row(c("seashell",   "Seashell",      "#FFF7EF", "#5A2E1B"),
                            c("tangerine",  "Tangerine",     "#FF844D", "#3A1807")),
                  combo_row(c("lavender",   "Muted Lavender", "#CCC3EB", "#4E3B53"),
                            c("plum",       "Deep Plum",      "#4E3B53", "#CCC3EB")),
                  combo_row(c("marigold",   "Soft Marigold", "#FFE08C", "#713443"),
                            c("blush",      "Deep Blush",    "#E36887", "#3D0F1F")),
                  combo_row(c("butternut",  "Butternut",     "#FFA175", "#5C0702"),
                            c("cherry",     "Deep Cherry",   "#5C0702", "#FFA175")),
                  combo_row(c("olive",      "Olive Green",   "#4D694E", "#FFF3D5"),
                            c("beige",      "Beige Cream",   "#FFF3D5", "#4D694E"))
                )
              ),

              menu_view(
                "keys", "Keyboard shortcuts",
                div(
                  class = "menu-keys",
                  key_row(c("\u2190", "\u2192"), "Previous / next filter"),
                  key_row(c("\u2191", "\u2193"), "Density \u00b15 (Shift \u00b11)"),
                  key_row("C", "Hold to see the original"),
                  key_row("M", "Change view mode"),
                  key_row("S", "Surprise me"),
                  key_row("R", "Reset everything"),
                  key_row("F", "Fullscreen"),
                  tags$label(class = "keys-toggle",
                             tags$input(type = "checkbox", id = "shortcuts-toggle", checked = NA),
                             " Keyboard shortcuts on")
                )
              )
            )
          )
        )
      )
    ),

    # ---- Hero ----
    tags$header(
      id = "top", class = "sec hero",
      art_img("lily-pink.jpg", "art-hero", eager = TRUE, `data-speed` = "0.38", `data-zoom` = "0.22", `data-rot` = "-7"),
      div(
        class = "wrap",
        div(
          class = "hero-copy rv-kids",
          span(class = "eyebrow", "Studio & Archive"),
          h1(class = "display", "Retro", tags$em("Lens.")),
          p(class = "hero-p",
            "Twenty-one analog moods, one density slider. Rejecting the flat preset ",
            "for photographs with grain, tone and atmosphere."),
          div(
            class = "hero-cta",
            tags$a(class = "pill lg", href = "#studio", "Start editing"),
            tags$a(class = "link-quiet", href = "#archive", "See the archive")
          )
        )
      )
    ),

    # ---- Process ----
    tags$section(
      id = "process", class = "sec process",
      # The stage is pinned to the screen while the steps play out (see JS).
      div(
        class = "pin",
        art_img("lily-red.jpg", "art-left pin-art on", `data-step` = "0"),
        art_img("magnolia.jpg", "art-left pin-art", `data-step` = "1"),
        art_img("lily-pink.jpg", "art-left pin-art", `data-step` = "2"),
        div(
          class = "wrap process-grid",
          div(
            class = "process-copy rv-kids",
            tags$h2(class = "display h-sec", "The Architecture", tags$br(), "of Light."),
            p(class = "sub",
              "Our process is a deliberate rejection of one-tap presets. Every photograph ",
              "is treated as its own commission: chosen, then tuned by hand.")
          ),
          div(
            class = "steps",
            step_item("01", "Upload & Vision",
                      "Drop in, paste or browse for a PNG, JPG or WebP. The photo you bring is the only starting point."),
            step_item("02", "Choose a Mood",
                      "Twenty-one looks, from Sepia to Cyanotype, each previewed on your own photo in the archive."),
            step_item("03", "Tune the Density",
                      "Slide from the opposite effect, through the untouched original, to pushed further. Download at full size.")
          )
        )
      )
    ),

    # ---- Studio (the editor, unchanged apart from where the filters live) ----
    tags$section(
      id = "studio", class = "sec studio",
      art_img("magnolia.jpg", "art-studio", `data-speed` = "0.3", `data-zoom` = "0.16", `data-rot` = "5"),
      div(
        class = "wrap",
        div(
          class = "sec-head rv-kids",
          div(
            span(class = "eyebrow", "Photo filter studio"),
            tags$h2(class = "display h-sec", "The Studio."),
            p(class = "sub", "Upload a photo. Pick a mood. Relive the film era.")
          ),
          conditionalPanel(
            "output.has_image",
            div(
              class = "dl-wrap",
              div(
                class = "dl-split",
                downloadButton("download", "Download", class = "btn-download-top dl-main"),
                tags$button(
                  type = "button", id = "dl_fmt_btn", class = "dl-fmt",
                  `aria-haspopup` = "listbox", `aria-expanded` = "false", `aria-controls` = "dl_menu",
                  `aria-label` = "File format: .png",
                  span(class = "dl-fmt-label", ".png"), icon_chevron
                ),
                # the real input Shiny reads; the visible menu below just sets it
                tags$select(
                  id = "dl_format", class = "dl-native", tabindex = "-1", `aria-hidden` = "true",
                  tags$option(value = "png", ".png"),
                  tags$option(value = "jpeg", ".jpg"),
                  tags$option(value = "webp", ".webp")
                )
              ),
              div(
                id = "dl_menu", class = "dl-menu", role = "listbox", tabindex = "-1",
                `aria-label` = "File format",
                dl_option("png", ".png", "Lossless", selected = TRUE),
                dl_option("jpeg", ".jpg", "Small"),
                dl_option("webp", ".webp", "Smallest")
              )
            )
          )
        ),

    sidebarLayout(
      sidebarPanel(
        width = 4,
        fileInput("image", "1. Upload your photo",
                  accept = c("image/png", "image/jpeg", "image/webp")),

        tags$h4(class = "section-label", "2. Choose a filter"),
        tags$a(class = "archive-btn", href = "#archive", "Filters archive"),

        div(
          class = "density-head",
          tags$h4(class = "section-label", "3. Set filter density"),
          div(
            class = "density-input",
            tags$input(
              id = "density_num", type = "number", class = "density-num",
              min = -100, max = 100, step = 1, value = 0,
              `aria-label` = "Filter density percentage, from -100 to 100"
            ),
            span("%")
          )
        ),
        sliderInput("density", NULL, min = -100, max = 100, value = 0, step = 1, post = "%"),
        tags$div(
          class = "density-legend",
          tags$div(tags$span(class = "legend-pct legend-neg", "-100%"), " = opposite effect"),
          tags$div(tags$span(class = "legend-pct legend-zero", "-50%"), " = original photo"),
          tags$div(tags$span(class = "legend-pct legend-pos", "0%"), " = filter's normal look"),
          tags$div(tags$span(class = "legend-pct legend-over", "100%"), " = pushed further")
        ),

        div(
          class = "look-actions",
          conditionalPanel(
            condition = "output.has_image",
            div(
              class = "look-btns",
              tags$button(type = "button", id = "btn-share", class = "btn tool-btn",
                          title = "Copy a link that carries this look", "Copy share link"),
              tags$button(type = "button", id = "btn-save-look", class = "btn tool-btn",
                          title = "Save this look in this browser", "Save look")
            )
          ),
          span(id = "my-looks", class = "my-looks")
        )
      ),
      mainPanel(
        width = 8,
        div(
          id = "preview-box",
          class = "mode-filtered",
          div(id = "busy-bar"),

          # ---- shown once a photo is loaded ----
          conditionalPanel(
            condition = "output.has_image",

            div(
              class = "status",
              textOutput("status", inline = TRUE),
              span(
                class = "mode-hint h-filtered",
                "Press and hold the photo to peek at the original."
              ),
              span(
                class = "mode-hint h-split",
                "Drag across the photo to move the divider."
              ),
              span(
                class = "mode-hint h-original",
                "Showing the original photo."
              )
            ),

            div(
              class = "toolbar",
              div(
                class = "seg-group", role = "group", `aria-label` = "View mode",
                tags$button(type = "button", class = "seg", `data-mode` = "filtered",
                            `aria-pressed` = "true", "Filtered"),
                tags$button(type = "button", class = "seg", `data-mode` = "split",
                            `aria-pressed` = "false", "Split"),
                tags$button(type = "button", class = "seg", `data-mode` = "original",
                            `aria-pressed` = "false", "Original")
              ),
              div(
                class = "tool-row",
                actionButton("undo", "Undo", class = "tool-btn", title = "Undo (Ctrl+Z)", disabled = NA),
                actionButton("redo", "Redo", class = "tool-btn", title = "Redo (Ctrl+Y)", disabled = NA),
                tags$button(type = "button", id = "btn-surprise",
                            class = "btn tool-btn tool-primary", title = "Pick a random filter (S)",
                            "Surprise me"),
                actionButton("rotate", "Rotate 90\u00b0", class = "tool-btn",
                             title = "Rotate the photo clockwise"),
                actionButton("flip", "Flip", class = "tool-btn",
                             title = "Mirror the photo left to right"),
                actionButton("reset_all", "Reset", class = "tool-btn",
                             title = "Back to the original photo (R)"),
                tags$button(type = "button", id = "btn-expand", class = "btn tool-btn",
                            title = "Fullscreen preview (F)", "Expand"),
                actionButton("add_layer", "+ Add as layer", class = "tool-btn",
                             title = "Keep this filter and stack another one on top"),
                uiOutput("layer_chips", inline = TRUE)
              )
            ),

            div(
              id = "cmp", class = "cmp",
              div(id = "orig_img", tags$img(src = "data:image/gif;base64,R0lGODlhAQABAAAAACwAAAAAAQABAAA=", alt = "Original photo", draggable = "false")),
              div(id = "filt_img", tags$img(src = "data:image/gif;base64,R0lGODlhAQABAAAAACwAAAAAAQABAAA=", alt = "Photo with the selected filter", draggable = "false")),
              span(class = "tag tag-original", "Original"),
              span(class = "tag tag-before", "Before"),
              span(class = "tag tag-after", "After"),
              div(
                id = "cmp-handle", class = "cmp-handle",
                role = "slider", tabindex = "0",
                `aria-label` = "Before and after divider",
                `aria-valuemin` = "0", `aria-valuemax` = "100", `aria-valuenow` = "50"
              ),
              # appears when the pointer comes close to it (always visible on touch screens)
              tags$button(type = "button", id = "photo-x", class = "photo-x",
                          title = "Remove photo", `aria-label` = "Remove photo", icon_x)
            )
          ),

          # ---- shown until a photo is loaded ----
          conditionalPanel(
            condition = "!output.has_image",
            div(
              id = "dropzone", class = "empty-state", role = "button", tabindex = "0",
              "Drop a photo here, click to browse, or paste one."
            )
          )
        )
      )
    )
      )   # end .wrap
    ),    # end studio section

    # ---- Archive: the filters as bento tiles ----
    tags$section(
      id = "archive", class = "sec archive",
      art_img("lily-red.jpg", "art-archive", `data-speed` = "-0.28", `data-zoom` = "0.18", `data-rot` = "-6"),
      div(
        class = "wrap",
        div(
          class = "sec-head rv-kids",
          div(
            tags$h2(class = "display h-sec", "The Archives."),
            p(class = "sub", "Sample previews to start with. Upload a photo and every tile re-renders on it.")
          ),
          tags$a(class = "pill lg", href = "#studio", "Back to the studio")
        ),
        filter_grid()
      )
    ),

    # ---- Statement ----
    tags$section(
      class = "sec statement",
      art_img("bloom-spray.jpg", "art-bg", `data-speed` = "0.3", `data-zoom` = "0.3", `data-rot` = "4"),
      div(
        class = "wrap rv-kids",
        span(class = "stmt-icon", leaf_svg),
        tags$h2(class = "display", "Never a generic filter."),
        p("Every look stays adjustable, from the opposite effect, through the untouched ",
          "original, to pushed further, so no two edits end up the same."),
        tags$a(class = "pill lg", href = "#studio", "Edit a photo")
      )
    ),

    # ---- Footer ----
    tags$footer(
      class = "foot",
      art_img("magnolia.jpg", "art-foot", `data-speed` = "0.25", `data-zoom` = "0.2", `data-rot` = "-5"),
      div(class = "ghost", `aria-hidden` = "true", "RETRO"),
      div(
        class = "wrap",
        div(
          class = "foot-top",
          div(
            class = "foot-brand",
            tags$h2(class = "display", "Retro Lens."),
            div(class = "tag-serif", "Analog moods, on demand."),
            p(class = "sub",
              "An independent photo filter studio for modern, atmospheric images. ",
              "Twenty-one looks, one density slider.")
          ),
          div(
            class = "foot-col",
            tags$h4("Explore"),
            tags$a(href = "#process", "The process"),
            tags$a(href = "#studio", "The studio"),
            tags$a(href = "#archive", "The archives")
          ),
          div(
            class = "foot-col",
            tags$h4("Popular looks"),
            span("Sepia"), span("Noir"), span("Cyanotype"), span("Sunset")
          ),
          div(
            class = "foot-col",
            tags$h4("Shortcuts"),
            span("\u2190 \u2192  switch filter"),
            span("\u2191 \u2193  density"),
            span("S  surprise me"),
            span("C  hold to compare")
          )
        ),
        div(
          class = "foot-bar",
          span("\u00a9 ", tags$span(id = "yr"), " Retro Lens Studio. All rights reserved."),
          span(class = "foot-mid",
               tags$a(class = "foot-gh", href = "https://github.com/BERSERKER1706",
                      target = "_blank", rel = "noopener noreferrer",
                      title = "github.com/BERSERKER1706", "GitHub")),
          span("Built with R \u00b7 Shiny \u00b7 magick")
        )
      )
    ),

    # ---- Mini preview (appears when the editor is scrolled out of view) ----
    tags$button(
      id = "dock", type = "button", `aria-label` = "Back to the preview",
      tags$img(id = "dock-img", alt = "",
               src = "data:image/gif;base64,R0lGODlhAQABAAAAACwAAAAAAQABAAA="),
      span(id = "dock-status"),
      tags$small("Back to the studio \u2191")
    )
  )
}


# ---- R/server.R ----
# =========================================================
# SERVER
#   Everything live (preview, tiles) works on a 1400px copy of the photo.
#   Only Download touches the full-size photo, in a background worker when
#   `future` + `promises` are installed. Images reach the browser as small JPEGs
#   through custom messages, so the DOM is never re-created.
# =========================================================

server <- function(input, output, session) {

  # ---- Edit state ----------------------------------------------------------
  layers         <- reactiveVal(list())   # committed layers: list(list(filter, density), ...)
  current_filter <- reactiveVal("Original")  # the filter being edited right now
  density_now    <- reactiveVal(0)        # slider scale: 0 = the filter's normal look
  rotation       <- reactiveVal(0)        # 0 / 90 / 180 / 270
  flipped        <- reactiveVal(FALSE)
  photo          <- reactiveVal(NULL)     # list(full, work, id, path) once a photo is loaded
  pending_look   <- reactiveVal(NULL)     # a look from a link/preset, waiting for a photo
  hist <- reactiveValues(past = list(), future = list(), present = NULL)

  toast <- function(msg) session$sendCustomMessage("toast", msg)

  # Sets density everywhere at once: server value, slider and the typed box.
  set_density <- function(v) {
    v <- as.numeric(v)
    density_now(v)
    updateSliderInput(session, "density", value = v)
    session$sendCustomMessage("density_num", v)
  }

  edit_state <- reactive(list(
    layers = layers(), filter = current_filter(), density = as.numeric(density_now()),
    rot = as.numeric(rotation()), flip = flipped()
  ))

  restore <- function(st) {
    layers(st$layers)
    current_filter(st$filter)
    set_density(st$density)
    rotation(st$rot)
    flipped(st$flip)
  }
  reset_edits <- function() restore(blank_state())

  # ---- Undo / redo ---------------------------------------------------------
  # Each distinct edit state becomes a history step. Slider drags are collapsed
  # (350 ms debounce) so one drag is one step, not fifty.
  commit_history <- function() {
    st <- isolate(edit_state())
    if (is.null(hist$present) || identical(st, hist$present)) return(invisible())
    hist$past <- c(utils::tail(hist$past, 59L), list(hist$present))
    hist$future <- list()
    hist$present <- st
  }
  edit_state_slow <- debounce(edit_state, 350)
  observeEvent(edit_state_slow(), {
    req(photo())
    commit_history()
  }, ignoreInit = TRUE)

  observeEvent(input$undo, {
    req(photo())
    commit_history()                      # fold in an edit that is still inside the debounce window
    n <- length(hist$past)
    req(n > 0L)
    st <- hist$past[[n]]
    hist$future <- c(list(hist$present), hist$future)
    hist$past <- hist$past[-n]
    hist$present <- st
    restore(st)
  })
  observeEvent(input$redo, {
    req(photo())
    commit_history()
    req(length(hist$future) > 0L)
    st <- hist$future[[1L]]
    hist$past <- c(hist$past, list(hist$present))
    hist$future <- hist$future[-1L]
    hist$present <- st
    restore(st)
  })

  # Tells the browser which buttons to enable, and how many layers exist
  observe({
    session$sendCustomMessage("edit_state", list(
      undo = length(hist$past) > 0L, redo = length(hist$future) > 0L, layers = length(layers())
    ))
  })

  # ---- Choosing a filter ---------------------------------------------------
  # The name comes from the browser, so it is checked against the real list.
  observeEvent(input$filter_click, {
    req(input$filter_click %in% filter_names)
    current_filter(input$filter_click)
    set_density(0)
  })
  observeEvent(current_filter(), {
    session$sendCustomMessage("select_thumb", current_filter())
  }, ignoreInit = TRUE)

  # Shiny already debounces slider input by 250 ms; the browser also shows an
  # instant approximation meanwhile (APP_JS), so the wait is not felt.
  observeEvent(input$density, density_now(as.numeric(input$density)))

  # ---- Stacking filters ----------------------------------------------------
  observeEvent(input$add_layer, {
    req(photo())
    if (current_filter() == "Original") return(toast("Pick a filter first, then add it as a layer"))
    if (length(layers()) >= MAX_LAYERS) return(toast(paste0("Up to ", MAX_LAYERS, " layers")))
    layers(c(layers(), list(mk_layer(current_filter(), density_now()))))
    current_filter("Original")
    set_density(0)
    toast("Layer added. Pick the next filter")
  })
  observeEvent(input$layer_remove, {
    i <- suppressWarnings(as.integer(input$layer_remove))
    l <- layers()
    req(!is.na(i), i >= 1L, i <= length(l))
    layers(l[-i])
  })

  output$layer_chips <- renderUI({
    l <- layers()
    if (!length(l)) return(NULL)
    tagList(lapply(seq_along(l), function(i) {
      span(class = "layer-chip",
           span(paste0(i, ". ", l[[i]]$filter, " ", sprintf("%+d%%", as.integer(l[[i]]$density)))),
           tags$button(
             type = "button", `aria-label` = paste("Remove layer", i), title = "Remove this layer",
             onclick = sprintf("Shiny.setInputValue('layer_remove', %d, {priority: 'event'})", i),
             HTML("&times;")))
    }))
  })

  # ---- Looks: share links and saved presets -------------------------------
  # A look is the whole edit as a short code. The browser keeps saved looks in
  # localStorage and puts the code in the link; the server only validates it.
  observeEvent(input$share_look, {
    req(photo())
    commit_history()
    session$sendCustomMessage("copy_look", encode_look(isolate(edit_state())))
  })
  observeEvent(input$save_look, {
    req(photo())
    name <- substr(trimws(as.character(input$save_look)), 1L, 24L)
    req(nzchar(name))
    session$sendCustomMessage("store_look", list(name = name, code = encode_look(isolate(edit_state()))))
  })
  observeEvent(input$apply_look, {
    st <- decode_look(input$apply_look)
    if (is.null(st)) return(toast("That look link is not valid"))
    if (is.null(photo())) {
      pending_look(st)
      return(toast("Look ready. Upload a photo to apply it"))
    }
    restore(st)
    toast("Look applied")
  })

  # ---- Loading / removing a photo -----------------------------------------
  # A bad file never reaches the preview code: it becomes a notification and
  # the previous photo (if any) stays on screen.
  observeEvent(input$image, {
    req(input$image)
    p <- tryCatch(
      load_photo(input$image$datapath),
      photo_error = function(e) {
        showNotification(conditionMessage(e), type = "error"); NULL
      },
      error = function(e) {
        message("[retro-lens] could not load upload: ", conditionMessage(e))
        showNotification("Sorry, that photo could not be processed.", type = "error"); NULL
      }
    )
    if (is.null(p)) return()
    photo(p)
    reset_edits()
    hist$past <- list(); hist$future <- list(); hist$present <- blank_state()
    session$sendCustomMessage("photo_ready", TRUE)
    stream_thumbnails(p)
    if (!is.null(pending_look())) {          # a look from a link/preset was waiting
      restore(pending_look())
      pending_look(NULL)
      toast("Look applied")
    }
  })

  # "Remove photo": back to the starting screen, as if nothing had been uploaded.
  observeEvent(input$remove_photo, {
    req(photo())
    thumb_token <<- thumb_token + 1L          # stop any tiles still streaming in
    photo(NULL)
    reset_edits()
    hist$past <- list(); hist$future <- list(); hist$present <- NULL
    session$sendCustomMessage("photo_removed", TRUE)
  })

  # ---- Archive tiles: streamed in one at a time ---------------------------
  # Rendering 21 filters in one go froze the session (and every other user).
  # Instead each tile is rendered in its own event-loop turn, so clicks and
  # slider moves are still answered between tiles. A newer upload (or removing
  # the photo) cancels the chain through the token.
  thumb_token <- 0L
  stream_thumbnails <- function(p) {
    thumb_token <<- thumb_token + 1L
    mine <- thumb_token
    src <- image_resize(p$work, paste0(THUMB_SIDE, "x", THUMB_SIDE, ">"))
    step <- function(i) {
      if (i > length(filter_names) || mine != thumb_token || session$isClosed()) return(invisible())
      fn <- filter_names[i]
      uri <- tryCatch(
        encode_uri(apply_filter_by_name(src, fn, 1), quality = 82),
        error = function(e) {
          message("[retro-lens] thumbnail '", fn, "' failed: ", conditionMessage(e)); NULL
        }
      )
      session$sendCustomMessage("thumb", list(name = fn, src = uri))
      later::later(function() step(i + 1L), 0.01)
    }
    later::later(function() step(1L), 0.05)
  }

  # ---- Rotate / flip / reset ----------------------------------------------
  # Rotation is applied first, then the mirror. When the photo is mirrored, a
  # clockwise turn on screen is a counter-clockwise turn before the mirror.
  observeEvent(input$rotate, {
    req(photo())
    step <- if (flipped()) -90 else 90
    rotation((rotation() + step) %% 360)
  })
  observeEvent(input$flip, {
    req(photo())
    flipped(!flipped())
  })
  observeEvent(input$reset_all, {
    req(photo())
    reset_edits()
    toast("Back to the original photo")
  })

  # Drives the conditional panels (and the Download button) in the UI
  output$has_image <- reactive(!is.null(photo()))
  outputOptions(output, "has_image", suspendWhenHidden = FALSE)

  output$status <- renderText({
    req(photo())
    d <- density_now()
    n <- length(layers())
    parts <- c(
      if (current_filter() != "Original") paste0(current_filter(), " at ", if (d > 0) "+" else "", d, "%"),
      if (n > 0L) paste(n, if (n == 1L) "layer" else "layers")
    )
    if (!length(parts)) "Original photo" else paste(parts, collapse = " + ")
  })

  # ---- Live preview -------------------------------------------------------
  base_work <- reactive({
    p <- req(photo())
    rotate_flip(p$work, rotation(), flipped())
  })

  layers_key <- reactive(paste(
    vapply(layers(), function(l) paste0(l$filter, ":", l$density), character(1)), collapse = "|"
  ))

  orig_uri <- bindCache(
    reactive(encode_uri(base_work(), quality = 88)),
    photo()$id, rotation(), flipped()
  )

  filt_uri <- bindCache(
    reactive({
      base <- base_work()   # outside tryCatch: req() inside it would be mistaken for a filter error
      out <- tryCatch(
        apply_layers(base, layers(), current_filter(), density_now()),
        error = function(e) {
          message("[retro-lens] filter failed: ", conditionMessage(e))
          showNotification("That filter failed on this photo.", type = "error", id = "filter_err")
          NULL
        }
      )
      req(out)
      encode_uri(out, quality = 86)
    }),
    photo()$id, rotation(), flipped(), layers_key(), current_filter(), density_now()
  )

  observe(session$sendCustomMessage("set_img", list(id = "orig_img", src = orig_uri())))
  observe(session$sendCustomMessage("set_img", list(
    id = "filt_img", src = filt_uri(),
    alt = paste("Photo with the", if (current_filter() == "Original") "selected" else current_filter(), "filter")
  )))

  # ---- Download: the only place the full-size photo is processed ----------
  # With `future` + `promises` installed it renders in a background worker, so
  # other visitors (and this visitor's slider) stay responsive meanwhile.
  output$download <- downloadHandler(
    filename = function() {
      fmt <- if (input$dl_format %in% c("png", "jpeg", "webp")) input$dl_format else "png"
      download_name(input$image$name, current_filter(), if (fmt == "jpeg") "jpg" else fmt)
    },
    content = function(file) {
      p <- photo()
      validate(need(!is.null(p), "Upload a photo first."))
      spec <- list(
        path = p$path, layers = layers(), filter = current_filter(),
        density = as.numeric(density_now()), rot = as.numeric(rotation()), flip = flipped(),
        format = if (input$dl_format %in% c("png", "jpeg", "webp")) input$dl_format else "png"
      )
      if (async_available()) {
        boot <- worker_bootstrap()
        promises::then(
          future::future({
            suppressPackageStartupMessages(library(magick))
            eval(parse(text = boot), envir = globalenv())
            render_export(spec, out_file)
            TRUE
          }, globals = list(boot = boot, spec = spec, out_file = file), seed = NULL),
          onFulfilled = function(ok) invisible(NULL)
        )
      } else {
        withProgress(message = "Rendering the full-size photo", value = 0.3, {
          render_export(spec, file, img = p$full)
        })
      }
    }
  )
}


