art_dir <- file.path(tempdir(), "retro-lens-art")
dir.create(art_dir, showWarnings = FALSE, recursive = TRUE)
for (nm in names(art_files)) {
  writeBin(base64enc::base64decode(paste(art_files[[nm]], collapse = "")), file.path(art_dir, nm))
}
rm(art_files)
addResourcePath("art", art_dir)

ui <- build_ui()
shinyApp(ui, server)
